text:
\begin{assumption}[Scalar Cardy limit]\label{ass:cardy}
For every bounded Jordan quadrilateral $Q$ with four distinct marked
boundary points, the critical crossing probability converges, as
$\eps\downarrow0$, to Cardy's conformally invariant value.
\end{assumption}

\begin{proposition}[Calibration]\label{in:calibration}
There are constants $c,B\in(0,\infty)$ such that
\begin{equation}\label{in:calibration-eq}
 m_\eps q_\eps S_\eps\longrightarrow c,
 \qquad q_\eps\E N_\eps\longrightarrow B.
\end{equation}
Moreover,
\begin{equation}\label{in:comparison}
 f(R)\asymp A(b_*,R).
\end{equation}
\end{proposition}

\begin{lemma}[Exponent without an amplitude]\label{in:exponent}
Under Assumption~\ref{ass:cardy},
\begin{equation}\label{in:exponent-eq}
 f(R)=R^{-5/4+o(1)}\qquad(R\to\infty).
\end{equation}
\end{lemma}

\begin{lemma}[The cap identity]\label{an:caps}
For every coloring of the annulus,
\begin{equation}\label{an:cap-equation}
 H_{\mathsf b}-H_{\mathsf w}=\mathbf 1_{\mathcal T}.
\end{equation}
Consequently the signed difference between the two inner cap states is
transferred to the same signed difference at the outer cycle, multiplied
by the indicator of four-interface transmission.  The identity remains
valid under composition across several cycles.
\end{lemma}

\begin{proposition}[Modulus equation]\label{sp:annular-pde}
The functions $T^\pm$ are smooth on $(0,\infty)\times\mathcal X$ and
satisfy
\begin{equation}\label{sp:pde}
 \partial_pT=(L+B_p\cdot\nabla)T,
 \qquad
 L=\frac18\sum_{w=x,y}
 \left(3\sum_{i=1}^4\partial_{w_iw_i}
 +\sum_{i=1}^4\sum_{j\ne i}
       \cot\frac{w_i-w_j}{2}\,\partial_{w_i}\right).
\end{equation}
For every $p_0>0$ and every fixed finite derivative order $k$,
the vector field $B_p$ extends smoothly across angle collisions and
\[
 \|B_p\|_{C^k}\le C_{k,p_0}e^{-p}\qquad(p\ge p_0).
\]
It is equivariant under permutations within either tuple, common
rotations, and cyclic relabelings.  In particular, its normal component
at every collision face is zero.
\end{proposition}

\begin{lemma}[Smoothing on the chamber]\label{sp:smoothing}
Fix $p_0>0$.  For either transmission function, or its sum or difference,
the transformed solution satisfies
\begin{equation}\label{sp:uniform-smoothing}
 \|W(p)\|_\infty+\operatorname{Lip}(W(p))\le C_{p_0}
 \qquad(p\ge p_0+2).
\end{equation}
The semigroup $P_t$ of $D$ is symmetric on $L^2(\mu)$ and, for every
$q>1$, maps $L^q(\mu)$ to bounded functions at every fixed positive
time.  At unit time the evolution in \eqref{sp:transformed-pde} maps
bounded functions to Lipschitz functions with a constant uniform in
the starting modulus $p\ge p_0$.
\end{lemma}

\begin{proposition}[Uniform transmission asymptotics]
\label{sp:transmission-asymptotics}
There are constants $K\ge0$, $\sigma>0$, and $C<\infty$ such that,
uniformly over the open angle chamber and all sufficiently large $p$,
\begin{align}
 \|W_-(p)\|_\infty&\le Ce^{-3p/4},
 &\|\Pi W_-(p)\|_\infty&\le C(1+p)e^{-p},
 \label{sp:odd-decay}\\
 T^\pm(p,x,y)&=e^{-\lambda p}
                   \bigl(Kh(x,y)+O(e^{-\sigma p})\bigr).
 \label{sp:rank-one-round}
\end{align}
Moreover,
\begin{equation}\label{sp:odd-regularity}
 \operatorname{Lip}(W_-(p))\le Ce^{-3p/4},\qquad
 \|W_-(p+\ell)-W_-(p)\|_\infty
        \le Ce^{-3p/4}\sqrt\ell\quad(0\le\ell\le1).
\end{equation}
The function $h$ is uniformly $1/3$-H\"older on the closed chamber.
\end{proposition}

\begin{lemma}[Domination before conditioning on end shapes]
\label{tr:domination}
Suppose a contribution to $M_{r,Lr}v$ is expressed, after exploring from
the auxiliary starting cycles, as an integral of an inner scalar
coefficient, a bounded middle test, and an outer signed state measure.
If the middle test is replaced with absolute error $F\ge0$, where $F$
depends only on the independent region just described, then the error
in output norm is at most
\begin{equation}
              C\|v\|_r\,\E_{\mathrm{core}}F+o(1)\|v\|_r.
\label{tr:domination-bound}
\end{equation}
The same bound applies to discarding an event there, by taking $F$ to
be its indicator.  The expectation is under the unweighted full-plane
comparison law; the bound is uniform over successful output seams.
\end{lemma}

\begin{lemma}[First-reduction tails]
\label{tr:tails}
For fixed $L$, the end-history subprobability masses satisfy, in the
mesh-first limit,
\begin{equation}
 \|\rho_j^{\rm in}\|_{\TV}
 \operatorname*{ess\,sup}_{\Sigma_{Lr}}
         \|\rho_k^{\rm out}(\cdot\mid\Sigma_{Lr})\|_{\TV}
      \le C 2^{-(2+\tau)j}2^{-(2+\tau)k}+o(1)
\label{tr:history-weight}
\end{equation}
for each used pair $(j,k)$.  Consequently, after inserting arbitrary
middle tests of modulus at most one, the same bound up to a constant holds
for the corresponding operator contribution on inputs of norm at most
one.  The part of the transfer not represented
by used pairs has norm at most
\begin{equation}
             C(n+1)^2L^{-2-\tau}+o(1).
\label{tr:unused}
\end{equation}
Both estimates are uniform for input messages of norm at most one and
for successful output seams.
\end{lemma}

\begin{corollary}[Fair-insertion message]
\label{tr:insertion}
There are $0<\nu<1$ and $C<\infty$ such that the following holds.  Insert
a nucleus at the center of a cut, with an independent fair color.  At
a seam of radius $s$, take the difference of the inside state laws
``with this insertion'' minus ``without this insertion,'' conditional
on the seam and with its screen success imposed.  Its message
$I_s$ satisfies
\begin{equation}
                            \|I_s\|_s\le C s^{-2-\nu}
\label{tr:insertion-bound}
\end{equation}
for all sufficiently large $s$.  The estimate remains valid in the
presence of fixed data outside the screened collar that do not enter
its inside.  The seam tests and the selected cycle are those of the
base process, without the insertion.
\end{corollary}

\begin{corollary}[Contraction of antisymmetric products]
\label{tr:wedge}
There are $\nu'>0$, $s_0<\infty$, and a fixed ratio $L>1$ such that,
for $r\ge s_0$ and $s/r=L^N$, the transfer
\[
          \mathcal M=M_{s/L,s}\cdots M_{r,Lr}
\]
with all intermediate seam successes imposed satisfies
\begin{equation}
 \|\mathcal M u\wedge\mathcal M v\|_\pi
       \le C(s/r)^{-2\lambda-\nu'}\|u\|_r\|v\|_r
\label{tr:wedge-bound}
\end{equation}
for any two zero-mass input messages $u,v\in\mathcal B_r$.  Here
$u\wedge v=u\otimes v-v\otimes u$ and $\|\cdot\|_\pi$ is the
projective tensor norm.  Fixed-factor unused intervals at the two
ends change only the constant.  No assertion of this contraction
through a failed intermediate cut is made.
\end{corollary}

\begin{lemma}[Intensity differentiation]\label{cl:derivative}
The function $f$ is continuously differentiable on $(0,\infty)$. For
every $R>0$, $K_R$ is absolutely integrable and
\begin{equation}\label{cl:derivative-eq}
 \frac R2 f'(R)=\int_{\R^2}K_R(y)\,dy.
\end{equation}
\end{lemma}

\begin{lemma}[Normalized insertion tail]\label{cl:tail}
There are constants $\xi>0$, $m_0<\infty$, and $C<\infty$ such that
for $m_0\le m\le R/100$,
\begin{equation}\label{cl:tail-eq}
 \int_{|y|>m}|K_R(y)|\,dy
 \le C f(R)\bigl(m^{-\xi}+R^{-\xi}\bigr).
\end{equation}
\end{lemma}

\begin{lemma}[Two-size determinant]\label{cl:determinant}
Let $\nu'>0$ be the exponent in Corollary~\ref{tr:wedge}.
There are constants $C,c>0$ such that, for sufficiently large $m$,
$100m\le R\le R'\le2R$, and almost every $0<|y|\le m$,
\begin{equation}\label{cl:determinant-eq}
 \bigl|K_R(y)f(R')-K_{R'}(y)f(R)\bigr|
 \le C(m/R)^{2\lambda+\nu'}+Ce^{-cm^2}.
\end{equation}
The constants are independent of the distance from $y$ to the origin.
\end{lemma}

\begin{proposition}[Summable logarithmic error]\label{cl:log-derivative}
There are constants $\alpha>0$ and $C<\infty$ such that
\begin{equation}\label{cl:log-derivative-eq}
 \left|\frac{Rf'(R)}{f(R)}+\lambda\right|
 \le CR^{-\alpha}
\end{equation}
for all sufficiently large $R$.
\end{proposition}

\begin{theorem}[Finite-graph comparison]\label{in:comparison}
For every two configurations $b,b'$ on $J$ and every configuration $a$
on $I$,
\[
 e^{-4\operatorname{arctanh}q_0}
 \leq
 \frac{\mu(\sigma_I=a\mid\sigma_J=b,\sigma_F)}
      {\mu(\sigma_I=a\mid\sigma_J=b',\sigma_F)}
 \leq e^{4\operatorname{arctanh}q_0}.
\]
Either conditional law may be replaced by an arbitrary mixture of
these laws. The bound is symmetric in the two terminal sets.
\end{theorem}

\begin{corollary}[Prediction from a nearby contour]
\label{tr:line-regularity}
In the setting of Proposition~\ref{tr:line-difference}, let $F$ be a
sigma-field containing the spins of $J'_s$, and write
$P_FX=\mathbb E[X\mid F]$. Then
\begin{equation}
\label{tr:line-regularity-eq}
 \limsup_{s\to\infty}\|M_{J_s}-P_FM_{J_s}\|_2
 \leq C_0(w/s)^{3/8}.
\end{equation}
The normalization on the approximating sum remains $s^{-7/8}$ even
when the two contours have different lengths.
\end{corollary}

\begin{lemma}[Buffered line and area moments]\label{fd:moments}
Fix \(A,c>0\), an integer \(p\ge1\), and \(\nu\in\{1,2\}\).
Let \(S\) be a set of lattice points of diameter at most \(As\) such that
\[
 |S\cap B_t(x)|\le A(t+1)^\nu\quad(t\ge0),
 \qquad |S|\le A s^\nu.
\]
Assume the Ising law has a free square-lattice neighborhood of width
\(cs\) about \(S\), with arbitrary pins beyond that neighborhood.
Then, for weights \(|a_x|\le1\),
\begin{equation}
 \mathbb E\left|\sum_{x\in S}a_x\sigma_x\right|^{2p}
 \le C_{p,A,c}\,s^{2p(\nu-1/8)}.
 \label{fd:moment-bound}
\end{equation}
This includes a fixed number of line segments or square contours
\((\nu=1)\), and area sums \((\nu=2)\).  It applies as well in a
buffered chart of a torus or cylinder.  No pin on \(S\) is allowed in
this assertion.
\end{lemma}

\begin{lemma}[Extreme rectangles in a ferromagnetic marginal]
\label{fd:mtp2}
Let \(p(a,b)>0\) be a marginal of a finite ferromagnetic Ising law with
arbitrary fields, on two disjoint sets of spins.  Set \(f=\log p\) and
\[
 L=f(+,+)+f(-,-)-f(+,-)-f(-,+).
\]
For every four configurations \(a,a',b,b'\),
\begin{equation}
 \left|f(a,b)+f(a',b')-f(a,b')-f(a',b)\right|\le L.
 \label{fd:extreme-rectangle}
\end{equation}
\end{lemma}

\begin{lemma}[Pointwise ratios with arbitrary common pins]
\label{fd:ratio}
Consider a finite ferromagnetic Ising graph, disjoint nonempty vertex sets
\(I,J\), and any fixed spins on a third set \(F\).
Delete \(F\), retaining its contribution as fields, and contract \(I\)
and \(J\) separately.  Let \(q_0\) be the zero-field FK probability that
the two contracted vertices are connected on this contracted, vertex-deleted
graph.  Then every two conditional spin laws on \(I\), obtained by
prescribing arbitrary configurations \(b,b'\) on \(J\), satisfy
\begin{equation}
 \exp(-4\operatorname{arctanh}q_0)
 \le\frac{\mu(\sigma_I=a\mid\sigma_J=b,\sigma_F)}
            {\mu(\sigma_I=a\mid\sigma_J=b',\sigma_F)}
 \le\exp(4\operatorname{arctanh}q_0)
 \quad\text{for every }a.
 \label{fd:pointwise-ratio}
\end{equation}
The same inequalities hold if either conditional law is replaced by any
mixture of these laws.  The assertion remains valid in the presence of
additional arbitrary finite external fields; those fields are set to zero
in the definition of \(q_0\).
\end{lemma}

\begin{lemma}[Ordering by boundary incidences]\label{if:incidence-order}
Let $\mu_0,\mu_1$ be two ferromagnetic Ising laws with the same
interactions and possibly different pin sets.  Let $C$ be the component
of the vertices free in both models which contains a specified connected
target.  Suppose that, for every edge $xy$ with $x\in C$ and $y\notin C$,
at least one of the following holds:
\begin{enumerate}
\item $y$ is pinned minus in model $0$;
\item $y$ is pinned plus in model $1$;
\item $y$ is pinned to the same sign in both models.
\end{enumerate}
Then $\mu_0|_C\preceq\mu_1|_C$.  The same assertion holds for a union
of target components with the corresponding incidence condition.
\end{lemma}

\begin{proposition}[Transmission]
\label{tr:transmission}
There is an exponent $\delta\in(0,1/8)$, chosen by decreasing the exponent
of Corollary~\ref{fd:patch-ratio} if necessary, with the following property.
Prescribe two ordered configurations on $S$, use identical common pins
elsewhere, and let $\Delta$ denote higher-law expectation minus lower-law
expectation. For an admissible separating cut at scales $w,s$, a bounded
observable $h$ supported on $T$, and $w$ sufficiently large,
\begin{equation}
\label{tr:transmission-eq}
 |\Delta h|
 \leq C\|h\|_\infty (w/s)^{-7/8+\delta}\Delta M_J.
\end{equation}
Equivalently, if $\|h\|_\infty\leq H$ for fixed $H>0$,
\begin{equation}
\label{tr:transmission-lower}
 \Delta M_J\geq c_H (w/s)^{7/8-\delta}|\Delta h|.
\end{equation}
The constants are uniform as $w/s$ decreases within the stated geometry.
\end{proposition}

\begin{lemma}[Doubled representation and ordered coupling]
\label{tr:doubled-coupling}
With partition sums at couplings $J_e=2K_e$, the law of $G$ is
\begin{equation}
\label{tr:doubled-weight}
 \mu_\tau(G)\ \propto\ Z_{U,+}(G)\,Z_{A,\tau}(W\setminus G).
\end{equation}
Conditional on $G$, the spins $\eta=-\xi$ on $G\cup U$ form the first
Ising law in \eqref{tr:doubled-weight}, independently of the common spins
on its complement. Put FK bonds $\omega$ on $G\cup U$. There is a coupling
of the original two Ising marginals, denoted again by $(\eta,\xi)$, for
which $\eta\geq\xi$ and
\begin{equation}
\label{tr:mean-connection}
 \eta_x-\xi_x=2\mathbf1_{\{x\longleftrightarrow U\}},
 \qquad
 \mathbb E\eta_x-\mathbb E\xi_x
 =2\mathbb P(x\longleftrightarrow U).
\end{equation}
Here and below a connection to $U$ uses actual open edges, and is false for
$x\notin G\cup U$.
\end{lemma}

\begin{lemma}[Spin products and addition of vertices]
\label{tr:site-gain}
Fix a set $P$ of pinned vertices, couplings $J_e\geq0$, and let
$Z_{P,\tau}(H)$ be the Ising partition sum on the induced graph with vertex
set $P\cup H$, with signs $\tau$ on $P$. Here $H\subseteq V\setminus P$ is
the retained free set. Then the following assertions hold.
\begin{enumerate}
\item With all pins plus, every spin-product expectation is nonnegative and
increases when nonnegative couplings are increased, free vertices and their
incident ferromagnetic edges are added, or additional spins are pinned plus.
The product in question involves only vertices present before the change.
\item For every finite set $Q\subseteq P\cup H$,
\begin{equation}
\label{tr:mixed-product}
 \left|\mathbb E_{P,\tau,H}\prod_{x\in Q}\sigma_x\right|
 \leq \mathbb E_{P,+,H}\prod_{x\in Q}\sigma_x.
\end{equation}
\item The function $H\mapsto Z_{P,+}(H)$ is log-supermodular. Moreover,
for $v\notin P\cup H$, the site gains satisfy
\begin{equation}
\label{tr:gain-comparison}
 \frac{Z_{P,\tau}(H\cup\{v\})}{Z_{P,\tau}(H)}
 \leq
 \frac{Z_{P,+}(H\cup\{v\})}{Z_{P,+}(H)}.
\end{equation}
\end{enumerate}
\end{lemma}

\begin{lemma}[Association and increasing conditioning]
\label{tr:increasing-conditioning}
The plus-agreement reference law of $(G,\omega)$ is positively associated.
The mixed-agreement law has an increasing density, depending only on $G$,
relative to this reference. Consequently, if $\mathcal E$ is any increasing
event of positive probability and $f$ is any increasing function, then
\begin{equation}
\label{tr:conditional-reference}
 \mathbb E_\tau[f\mid\mathcal E]\geq\mathbb E_+[f].
\end{equation}
There is no restriction on the number or placement of the pins in this
finite-graph assertion.
\end{lemma}

\begin{proposition}[Local domination]
\label{tr:local-domination}
Let $Q\subseteq W$ contain no pins. In $Q$, form the doubled model from two
independent Ising configurations with plus signs on every exterior
neighbor of $Q$, with the original couplings $K_e$. Call its auxiliary
set-and-bond law $\mathbb P_Q^{++}$. For every increasing function $f$ of
the auxiliary set and bonds internal to $Q$, and every positive-probability
increasing event $\mathcal E$ in the original doubled model,
\begin{equation}
\label{tr:local-domination-eq}
 \mathbb E_\tau[f\mid\mathcal E]\geq\mathbb E_Q^{++}[f].
\end{equation}
The same statement holds with $\mathcal E$ the sure event.
\end{proposition}

\begin{lemma}[Many sites joined across a rectangle]
\label{tr:many-sites}
Consider two independent plus-boundary Ising configurations in a rectangle
of scale $w$ and fixed aspect ratio, and their auxiliary disagreement
bonds. Let $L_1,L_2$ be straight lattice segments of lengths comparable to
$w$, in fixed compact bulk subsets of the rectangle, mutually separated
by a distance comparable to $w$. There are constants $c,p>0$, depending
only on this geometry, such that
\begin{equation}
\label{tr:many-sites-eq}
 \mathbb P_Q^{++}\bigl(
 |\{x\in L_1:x\longleftrightarrow L_2\}|\geq c w^{7/8}
 \bigr)\geq p.
\end{equation}
In particular a disagreement-bond connection between the segments has
probability bounded below.
\end{lemma}

\begin{lemma}[A surrounding disagreement circuit]
\label{tr:circuit}
In the doubled plus-boundary model on $B_{16w}$, a circuit of actual
disagreement bonds in $B_{4w}\setminus B_{3w/2}$ surrounding $B_{3w/2}$ has
probability at least a constant $p_0>0$ for all sufficiently large $w$.
\end{lemma}

\begin{proposition}[Mass at a source-connected patch]
\label{tr:mass}
Fix $a>0$. Let $b_0\subseteq z+B_w$, and let $L\subseteq z+B_w$ be a
horizontal or vertical lattice segment of length at least $aw$ and at
most $2w$. Suppose $z+B_{16w}$ is a free square-lattice neighborhood:
it contains no common or disagreement pins. Then in the doubled model
with arbitrary ordered pins outside this square,
\begin{equation}
\label{tr:mass-eq}
 \sum_{x\in L}\mathbb P(x\longleftrightarrow U)
 \geq c_a w^{7/8}\mathbb P(U\longleftrightarrow b_0).
\end{equation}
The constant and lower threshold for $w$ depend only on $a$. The same
statement holds inside an isometric planar chart of a torus or cylinder.
\end{proposition}

\begin{corollary}[Random and signed sources]
\label{tr:signed-transmission}
The conclusions of Proposition~\ref{tr:transmission} hold after averaging
over any ordered coupling of two random source configurations, with the
appropriate common Gibbs continuation given each source. In particular,
let $\mu$ be a Gibbs law with common pins and let $q=q(\sigma_S)$ be an
order-positive centered density for its source marginal. Then
\begin{equation}
\label{tr:signed-transmission-eq}
 \left|\mathbb E_\mu[qh]\right|
 \leq C\|h\|_\infty(w/s)^{-7/8+\delta}
                    \mathbb E_\mu[qM_J].
\end{equation}
The constants do not depend on the mass of the positive part of $q$.
\end{corollary}

\begin{corollary}[Ordered changes of domains and total variation]
\label{tr:ordered-tv}
Suppose two ordered Ising laws, possibly defined by different sets of
pins or different volumes, have a common free source contour $S_0$ such
that their conditional continuation from $S_0$ toward a target $T$ is the
same. Let an admissible cut $J$ lie between $S_0$ and $T$. Then
\eqref{tr:transmission-eq} holds for their expectation differences.
In particular, with total variation defined as the supremum of event
probability differences,
\begin{equation}
\label{tr:ordered-tv-eq}
 \|\mu_T^+-\mu_T^-\|_{\rm TV}
 \leq C(w/s)^{-7/8+\delta}
       \bigl(\mathbb E_{\mu^+}M_J-\mathbb E_{\mu^-}M_J\bigr).
\end{equation}
At fixed positive $w/s$, convergence of the magnetic difference to zero
therefore implies convergence in total variation on the buffered target.
\end{corollary}

\begin{theorem}[Annealed Voronoi crossing law]\label{thm:cardy}
For every bounded Jordan domain $D$ and every four distinct
counterclockwise boundary marks $a,b,c,d$, one has
\begin{equation}\label{eq:cardy}
 \lim_{\eps\downarrow0}\PP\bigl(\mathcal C_\eps(D;a,b,c,d)\bigr)
 =F(x)
 :=\frac{\displaystyle\int_0^x[u(1-u)]^{-2/3}\,\dd u}
          {\displaystyle\int_0^1[u(1-u)]^{-2/3}\,\dd u}
 =\frac{\Gamma(2/3)x^{1/3}}
        {\Gamma(1/3)\Gamma(4/3)}
        {}_2F_1\!\left(\frac13,\frac23;\frac43;x\right).
\end{equation}
\end{theorem}

\begin{lemma}[Two defects]\label{fields:defects}
For distinct edge-interior points $m,n$, subdivide the dual edges at these
points and take a uniform subgraph with odd degree at $m,n$ and even degree
elsewhere.  Then $K(m,n)$ is the expected number of circuits in this
subgraph.  The assertion also applies to distinct points on the same edge.
\end{lemma}

\begin{proposition}[Finite orthogonality]\label{fields:orthogonality-prop}
For distinct triangles $t,u$,
\begin{equation}\label{fields:orthogonal}
 \langle Z_t,Z_u\rangle=0,
 \qquad \|Z_t\|^2=\frac34.
\end{equation}
\end{proposition}

\begin{lemma}[No right bypass and its converse]\label{lemma:no-bypass}
A rim has no path of its own color joining two distinct rim vertices with
all its other points in the open right-hand disk.  Conversely, a simple
monochromatic circuit with this property, and with an opposite-colored site
in its right-hand disk, is a rim.
\end{lemma}

\begin{lemma}[Sandwich]\label{lemma:sandwich}
In an annular band, suppose that there are disjoint essential simple black
and white circuits, with the white circuit on the right of the black one
for the direction of the band.  There is a black rim, with this direction,
in the closed region between them.
\end{lemma}

\begin{proposition}[Closed-sum tail]\label{fields:closed-prop}
For every fixed bounded box $B\subset\C$ and every $a>0$, the full-plane
model of spacing $\eps$ satisfies
\begin{equation}\label{fields:closed}
 \lim_{\eps\downarrow0}
 \EE\!\sum_{\substack{P\text{ a rim},\ P\subset B\\\diam(P)\ge a}}
                   |Q_P(1)|^2=0.
\end{equation}
The corresponding full sums for $V_P$ vanish identically.
\end{proposition}

\begin{lemma}[Disjoint witnesses at fixed geometry]\label{prob:reimer}
For events $A,B$ in a finite product of fair bits, let $A\mathbin\square B$
mean that there are disjoint sets of coordinates certifying $A$ and $B$.
Then
\begin{equation}\label{prob:disjoint-product}
 \PP(A\mathbin\square B)\le\PP(A)\PP(B).
\end{equation}
In particular this inequality applies to bounded percolation tests
conditional on the Voronoi geometry, with disjoint used site sets.
\end{lemma}

\begin{lemma}[Mixed-color four arms]\label{lemma:mixed-four}
For some $c>0$ and $C<\infty$,
\begin{equation}\label{prob:mixed-four}
 \limsup_{\eps\downarrow0}
 \PP\left(\begin{array}{c}
 \text{four vertex-disjoint primal arms across }B(x,S)\setminus B(x,s),\\
 \text{with both colors represented}
 \end{array}\right)
 \le C(s/S)^{1+c}.
\end{equation}
The four colors need not alternate.
\end{lemma}

\begin{lemma}[Near-return bound]\label{lemma:near-return}
For some $c>0$ and $C<\infty$, and the same fixed-scale convention,
\begin{equation}\label{prob:near-return}
 \limsup_{\eps\downarrow0}
 \PP\left(\begin{array}{c}
 \text{some rim has two visits to }B(x,s)\text{ such that both}\\
 \text{complementary rim arcs between the visits leave }B(x,S)
 \end{array}\right)
 \le C(s/S)^{2+c}.
\end{equation}
The rim can be part of a global spherical completion.  The event is
bounded by a local monochromatic-arm test, without a union over rims.
\end{lemma}

\begin{theorem}[Bulk transport]\label{thm:bulk-transport}
From every sequence $\eps\downarrow0$ one can extract a subsequence and a
complex number $a$, depending only on that subsequence, such that
$\Rea a<1/2$ and the following holds in every bulk patch.  If
$f\in C_c^\infty(B(x,R))$ and $\overline B(x,6R)$ lies in the patch, then
\begin{equation}\label{transport:bulk}
 \max_{P:\,P\not\subset B(x,4R)}
       |Q_P(f)-aV_P(f)|\xrightarrow[\eps\to0]{\PP}0.
\end{equation}
As in the definition of a bulk patch, local tests may be set to zero on a
geometry event whose probability tends to zero.  The subsequence and
scalar are common to all patches and tests.
\end{theorem}

\begin{lemma}[Two-graph gate consistency]\label{lemma:gate-consistency}
Let $P,P'$ be oriented simple monochromatic rims in their respective
embedded triangulations.  Suppose their directed subpaths $\gamma,
\gamma'$ have common distinct initial and terminal vertices $v,w$ and
satisfy these conditions:
\begin{enumerate}[label=\textup{(\roman*)}]
\item each \emph{complete compared subpath} is present and monochromatic
in the other graph, with the same embedding;
\item at $v$ there is a shared gate circuit, both incoming rim rays lie
strictly in one gate fan, and both outgoing rays lie strictly in the
opposite fan;
\item the rim orientations and direction of crossing that gate agree.
\end{enumerate}
Then $\gamma=\gamma'$ as directed edge paths.  Each rim needs its
no-right-bypass property only in its own graph.
\end{lemma}

\begin{proposition}[The state cochain]\label{prop:state-cochain}
For every fixed connector, including its actual end charts, there are
functions $i_e^\eps(\sigma_s,\sigma_t)$ such that
\begin{equation}\label{plug:cycle}
 \begin{aligned}
 \widehat m_s+\widehat j_e-i_e^\eps&=o_{L^1}(1)
       &&\text{in every cycle experiment containing }e,\\
 \sum_e i_e^\eps&=o_{L^1}(1)
       &&\text{on the independent state product of every simple system}.
 \end{aligned}
\end{equation}
The same functions work in all completions.  For a fixed collection of
normalized short templates admitting uniform short completions,
\[
 \|i_e^\eps\|_{L^2(\mu_s\otimes\mu_t)}\le C h
\]
for all sufficiently small $\eps$, after increasing a common constant.
\end{proposition}

\begin{proposition}[Affine straight means]\label{prop:affine}
For $X=Q,V$ there is a scalar $a_h^X$, uniformly bounded in $h$, such
that every fixed straight transport in the countable family used below
has mean
\begin{equation}\label{affine:means}
 \EE_\mu i_e^\eps=a_h^X(z_t-z_s)+o(1).
\end{equation}
The same scalar applies to translations, common rotations and color
flips of the reference type.  All choices can be made simultaneously
for the two fields and countably many $h$.
\end{proposition}

\begin{lemma}\label{lemma:tangent-normalization}
The scalar of the tangent field is
\begin{equation}\label{affine:tangent}
 a_h^V=1.
\end{equation}
\end{lemma}

\begin{proposition}[Holomorphy]
\label{prop:holomorphy}
Every limit $F$ in Lemma~\ref{lemma:probe-compactness} is holomorphic in
$D$.
\end{proposition}

\begin{lemma}[Transport through an unchanged collar]
\label{buf:tilt}
Let $T$ be a separating contour and $W$ a farther contour, with a fixed
positive buffer between them.  Fix two outer Gibbs continuations,
independently of the data on the inner side of $T$.  They agree on the graph,
couplings, and fields between $T$ and $W$, and all their differences
are on or beyond $W$.  For any fixed data on the inner side of $T$,
the corresponding laws on $T$ differ by a positive tilt $w$ satisfying
\begin{equation}
 \frac{\sup w}{\inf w}\le K,
 \label{buf:tilt-bound}
\end{equation}
where $K$ depends only on the buffer geometry.  The same weight $w$
works for every change of the inner data.  Common pins and arbitrary
common finite fields are permitted wherever \Cref{in:ratio} permits
them.

If two laws $\nu_1,\nu_2$ on $T$ are compared in one continuation,
their laws in the other satisfy
\begin{equation}
 \norm{\nu_1^w-\nu_2^w}_{\TV}
 \le 2K\norm{\nu_1-\nu_2}_{\TV},
 \qquad
 d\nu_i^w=\frac{w\,d\nu_i}{\nu_i(w)}.
 \label{buf:tilt-tv}
\end{equation}
In the destination continuation, both tilted laws use the same further
Gibbs kernel given $T$.  Applying that kernel preserves the bound.
Remote data may first be conditioned on, or integrated out in the outer
Gibbs weights before the inner data are varied.
\end{lemma}

\begin{lemma}[Smeared moments and exponential tails]
\label{buf:moments}
Let $h_1,\ldots,h_m$ be fixed bounded piecewise regular profiles with
compact interior supports in a reference chart.  All joint polynomial
moments of the variables $X_{\delta,h_i}$ converge to the integrals
of the corresponding continuum spin correlations.  For every
$t<\infty$,
\begin{equation}
 \sup_{\delta\ \mathrm{small}}
 \E\exp\!\left(t\sum_{i=1}^m|X_{\delta,h_i}|\right)<\infty.
 \label{buf:exponential}
\end{equation}
Joint exponential expectations converge as well.  In particular the
weights in \eqref{buf:weight} have convergent normalizations and
uniformly integrable powers of every fixed positive order.

For two separated support regions with a fixed buffer, there is a
geometric constant $K$ such that
\begin{equation}
 \E[A U_{\delta,g}]\le K\E A
 \label{buf:weighted-tail}
\end{equation}
for every nonnegative function $A$ of the first region and every
normalized positive soft weight on the second.  The constant is
independent of $g$, its magnitude, and its complexity.
\end{lemma}

\begin{proposition}[Separated-source comparison]
\label{src:separated}
At the stopping scale just described, the exact finite-system source
coefficients satisfy
\begin{align}
 U_k^{\{\ell\}}
   &=Z_\ell v_k^{(d_\ell)}+o(1)
       &&\text{in marked norm}, \label{src:single-stop}\\
 \norm{U_k^S}_{r_k,\bullet}&=o(1)
       &&(|S|\geq2), \label{src:multiple-stop}\\
 c_k^S&=o(1)
       &&\bigl(|S|\geq2\text{ or }S
                         \text{ is a spin singleton}\bigr).
       \label{src:scalar-stop}
\end{align}
The ideal functions in \eqref{src:single-stop} are restricted to the
system, with their cutting squares contained in its interior. On tori
the conclusions hold as $a\to0$ and $N/\Delta_*\to\infty$.
All errors use the running normalization $r_k^{d(S)}$.
\end{proposition}

\begin{lemma}[The decaying graph]\label{flow:stable-graph}
There is $\epsilon>0$ such that, for every sufficiently small
$w_0\in W_0$, there is exactly one trajectory of
\eqref{flow:coordinate-map} with this initial stable coordinate,
$\sup_j(|t_j|+\norm{w_j}_{r_j})<\epsilon$, and
\[
        \sup_{j\ge0}\gamma_0^{-j}
                (|t_j|+\norm{w_j}_{r_j})<\infty.
\]
It satisfies
\begin{equation}\label{flow:stable-bound}
 |t_j|+\norm{w_j}_{r_j}\le C\norm{w_0}_{r_0}\gamma_0^j.
\end{equation}
Its initial thermal coordinate $t_0=\psi(w_0)$ is analytic, with
$\psi(0)=0$.  This graph is transverse to the thermal line.
\end{lemma}

\begin{proposition}[The temperature branch]\label{flow:branch}
There is $\lambda_0>0$ and a real analytic branch
$\beta_c:(-\lambda_0,\lambda_0)\to(0,\infty)$, with
$\beta_c(0)=\beta_0$, whose homogeneous effective backgrounds satisfy
\begin{equation}\label{flow:plane-decay}
       h_{j+1}=\mathcal R_j(h_j),\qquad
       \norm{h_j}_{r_j}\le C|\lambda|\gamma_0^j.
\end{equation}
The branch depends only on $J,V,\lambda$.
\end{proposition}

\begin{proposition}[Boundary backgrounds]\label{flow:boundary}
There are constants $C,\lambda_0>0$, independent of the allowed domain
and of its boundary type, with the following property.  For each fixed
$C^2$ Jordan domain $D$ there is $\eta_D>0$ such that, for sufficiently
small $a$, the effective background with any of the three prescribed
boundary conditions has the form
\begin{equation}\label{flow:domain-decomposition}
       H_j^{a,b}=\operatorname{Res}_{a,j}h_j+b_j^{a,b},
       \qquad \norm{b_j^{a,b}}_{r_j}
                       \le C|\lambda|\gamma^j,
\end{equation}
through all steps with $ar_j\le\eta_D$.
Every carrier of $b_j^{a,b}$ touches the physical boundary in the
above sense.  For free boundary conditions its functions are even;
for fixed boundary conditions they need not be even.
\end{proposition}

\begin{proposition}[Periodic backgrounds]\label{flow:torus}
For a sufficiently small fixed $\vartheta>0$, the periodic effective
background $H_j^N$ satisfies
\begin{align}
 \norm{H_j^N}_{r_j}&\le C|\lambda|\gamma^j,
                                      \label{flow:torus-small}\\
 \norm{H_j^N-\Pi_Nh_j}_{r_j}
       &\le C|\lambda|\gamma^j
                      \exp(-cN/r_j), \label{flow:torus-error}
\end{align}
whenever $r_j\le\vartheta N$.  The constants and the coupling
interval are independent of $N,j$.  On every fixed finite set of
scales, coefficients in a fixed plane chart converge to their plane
counterparts as $N\to\infty$, with the tails interpreted in the
weighted list norms.

For real $\lambda$ these backgrounds are real.  At every finite
volume the successive maps, including the preliminary map, retain
the exact partition identity with their scalar prefactors, and the
residual tilt defines a positive Gibbs probability.
\end{proposition}

\begin{lemma}[Pointwise comparison with common pins]\label{in:ratio}
Let $G$ be a finite graph with nonnegative pair couplings and arbitrary
finite real fields. Let $I,J,F$ be disjoint vertex sets, with $I,J$
nonempty, and prescribe arbitrary common spin values on $F$. Form the
graph obtained by deleting $F$ and contracting $I$ and $J$ separately;
parallel couplings are added. Let $q_0$ be the probability that the two
contracted vertices are FK-connected in the zero-field, cluster-weight
$2$ measure on this graph. For any configurations $a$ on $I$ and $b,b'$
on $J$,
\begin{equation}\label{in:ratio-bound}
 e^{-4\operatorname{arctanh}q_0}
 \leq
 \frac{\Prob(\sigma_I=a\mid\sigma_J=b,\sigma_F)}
      {\Prob(\sigma_I=a\mid\sigma_J=b',\sigma_F)}
 \leq e^{4\operatorname{arctanh}q_0}.
\end{equation}
Either conditional law may be replaced by a mixture of such laws.
All external fields, including those produced by the common pins,
are set to zero in the comparator defining $q_0$.
\end{lemma}

\begin{lemma}[Charge cancellation]
\label{rad:identity}
For every even list $X$,
\begin{equation}
 \E_0\left|\sum_i\mu_i z_i\right|^2
       =4\left(\frac{W_2(X)}{W_0(X)}\right)^2.
 \label{eq:rad-charge-identity}
\end{equation}
For the empty list both sides are zero.
\end{lemma}

\begin{lemma}[Nonzero disk responses]
\label{rad:calibration}
Let $\mathcal O_{1/8}(z)=\sigma_z$ and let
$\mathcal O_1(z)=e(z)$ be the symmetric average of the four incident
bond products.  With $m$ denoting infinite-plane critical
expectation, there are nonzero real constants $\kappa_d$ such that
\begin{equation}
 \lim_{R\to\infty}R^d\left(
       \E^+_{\mathrm{disk}(4R)}\mathcal O_d(0)
                             -m(\mathcal O_d(0))\right)=\kappa_d,
 \qquad d\in\{1/8,1\}.
 \label{eq:rad-micro-calibration}
\end{equation}
\end{lemma}

\begin{lemma}[Carrier geometry]
\label{rg:geometry}
For connected $A$ and $R=Lr$, with $L$ sufficiently large,
\begin{equation}
 N_R(U(A))\le C\bigl(1+L^{-1}N_r(A)\bigr).
 \label{rg:geometry-eq}
\end{equation}
Moreover $A+B_{5R}$ can be covered by at most
$C_L(1+N_r(A))$ squares of radius $r$.  These estimates hold on a torus
while $R$ is less than a fixed sufficiently small fraction of its side.
\end{lemma}

\begin{lemma}[Distinguished fields]
\label{rg:fields}
On carrier $B_{r_j}(z)$ define
\begin{equation}
 v_j^{(d)}(z)=r_j^d\pi P_{r_j,z}\mathcal O_d(z),
 \qquad d\in\{1,1/8\}.
 \label{rg:distinguished}
\end{equation}
For spin the projection removes no constant.  If $r_0$ is sufficiently
large, there are constants $0<c<C<\infty$, independent of $j$ and of the
large blocking ratio $L$, such that
\begin{equation}
 c\le\|v_j^{(d)}(z)\|_\infty\le C.
 \label{rg:field-norms}
\end{equation}
Their single-term marked norms are likewise bounded above and below.
For $R/r_j$ sufficiently large,
\begin{equation}
 c(r_j/R)^d\le |d_R(v_j^{(d)}(z))|
                    \le C(r_j/R)^d,
 \label{rg:field-response}
\end{equation}
where the disk is centered at $z$.
\end{lemma}

\begin{proposition}[Joint connection comparison]\label{cmp:joint}
In independent percolation on a finite hypergraph, with arbitrary hyperedge
probabilities in $[0,1]$, let $o$ be a node and let $A,T$ be node sets with
$A\ne\varnothing$. Then
\begin{equation}\label{cmp:joint-bound}
 \mathbb P(o\leftrightarrow A,\ o\leftrightarrow T)
 \ge \mathbb P(o\leftrightarrow A)
       \min_{a\in A}\mathbb P(a\leftrightarrow T).
\end{equation}
\end{proposition}

\begin{lemma}[Freshness and persistence]
\label{exp:freshness}
Conditional on any positive-probability finite revealed history, all
unrevealed bits are independent Bernoulli($q$). Moreover,
\eqref{exp:promise} holds at every step of the exploration.
\end{lemma}

\begin{lemma}
\label{exp:conditional-bad}
Immediately before any pending vertex is processed, its conditional
probability of being declared bad is less than $f$.
\end{lemma}

\begin{lemma}
\label{exp:bad-set}
For every deterministic set of $k$ distinct coarse vertices, the
probability under $\mathbb P_{\mathcal I}$ that all are processed and
declared bad is at most $f^k$.
\end{lemma}

\begin{lemma}[Neighboring-box relay]\label{geom:relay}
Let $v,x\in\mathbb Z^2$ be nearest neighbors. Let $G$ be a finite lattice
subgraph containing $D=Q_v\cup Q_x$ and all lattice edges internal to $D$.
Consider independent bond or site percolation on $G$, with parameter $q$ on
all bits internal to $D$ and arbitrary parameters elsewhere. If $o\in V(G)$
lies outside $D$, then
\begin{equation}\label{geom:relay-bound}
  \mathbb P\bigl(o\leftrightarrow B_v,\ o\not\leftrightarrow B_x\bigr)
  \le 13\eta.
\end{equation}
All connections in this statement are taken in $G$.
\end{lemma}

\begin{theorem}\label{thm:main}
For nearest-neighbor Bernoulli bond percolation on $\mathbb Z^3$, there is
almost surely no infinite open cluster at the bond critical parameter.
The same assertion holds for nearest-neighbor Bernoulli site percolation
at the site critical parameter.
\end{theorem}

\begin{lemma}\label{prelim:pc-below-one}
For both models on $\mathbb Z^3$, $p_c<1$.
\end{lemma}

\begin{lemma}[Choice of scales]\label{prelim:scales}
Under the preceding contradiction assumption, there are numbers
$f,\delta,\eta,\tau,\gamma\in(0,1)$, positive integers $m,K,R,r$, and
$q\in(p/2,p)$ with the following properties. First, $f<1/2$ and
\begin{equation}\label{prelim:contour-budget}
 \sum_{n\ge1}2n3^n(2f)^{n/7}<1.
\end{equation}
The error parameters satisfy
\begin{equation}\label{prelim:budgets}
 \delta+\frac{52\eta}{\delta}<f,\qquad
 \tau<\frac\eta4,\qquad \gamma<\delta,\qquad
 \frac{2\gamma}{\tau}<\frac\eta4.
\end{equation}
Let $M$ be the number of internal bits of $\Lambda_m$, and set
$\rho_0=(p/2)^{M+1}$. With $L=K(8m+5)^3$ and $\alpha=(1-p)^L$, we have
\begin{equation}\label{prelim:scale-inequalities}
 \frac4{K\rho_0}<\frac\eta4,\qquad
 R>m,\qquad \frac1{\alpha(R-m)}<\frac\eta4,\qquad r>100(R+1).
\end{equation}
For every $\ell\in\{2r,2r+1,10r\}$, $u\in\mathbb Z^3$, and quarter-face
$F$ of $\Lambda_\ell(u)$, independent parameter-$q$ percolation satisfies
\begin{equation}\label{prelim:quarterface}
 \mathbb P_q\bigl(\Lambda_m(u)\leftrightarrow F
              \text{ within }\Lambda_\ell(u)\bigr)>1-\gamma.
\end{equation}
\end{lemma}

\begin{hypothesis}[Scalar critical Cardy formula]
\label{hyp:cardy}
For every fixed bounded Jordan quad $Q=(D;a,b,c,d)$, the annealed
probability of $C_Q$ in fair-colored full-plane Poisson--Voronoi
percolation converges, as $\varepsilon\downarrow0$, to
\begin{equation}
 F(x)=\frac{\displaystyle\int_0^x [u(1-u)]^{-2/3}\,du}
 {\displaystyle\int_0^1 [u(1-u)]^{-2/3}\,du},
 \label{eq:cardy}
\end{equation}
where a conformal map from $D$ to the upper half-plane sends
$(a,b,c,d)$ to $(0,x,1,\infty)$.
\end{hypothesis}

\begin{theorem}[Quenched near-critical universality]
\label{thm:main}
Assume Hypothesis~\ref{hyp:cardy}. The expectations in
\eqref{eq:requested-scales} are finite and strictly positive for every
mesh, and both scales tend to zero as their mesh tends to zero.
There is a probability measure $\nu_\triangle$ on $\mathcal K$ such that
\begin{equation}
 \Law(\tau_\delta^\triangle)\Longrightarrow\nu_\triangle
 \qquad(\delta\downarrow0).
 \label{eq:triangular-reference}
\end{equation}
For the independently normalized Voronoi model,
\begin{equation}
 d_{\mathrm{BL}}\bigl(\Law(\tau_\varepsilon^V\mid\eta_\varepsilon),
                 \nu_\triangle\bigr)
 \xrightarrow[\varepsilon\downarrow0]{\PP}0.
 \label{eq:main-quenched}
\end{equation}
The conditional law averages all color marks and no geometry.
\end{theorem}

\begin{lemma}[Uniform critical arm inputs]\label{lem:arm-inputs}
For each model there are constants $C,c,\alpha,\beta>0$ and
$g\in(1,2)$ such that, for $b_e\le r\le s\le R$,
\begin{align}
 c(r/R)^g&\le A_e(r,R)\le C(r/R)^{1+\alpha},\label{eq:four-powers}\\
 C^{-1}A_e(r,s)A_e(s,R)&\le A_e(r,R)
       \le C A_e(r,s)A_e(s,R).\label{eq:qm}
\end{align}
The one-arm probability is at most $C(r/R)^\beta$, and the
polychromatic five-arm probability is at most $C(r/R)^2$.
The alternating three-arm probability in a half-plane in a standard
orientation is at most $C(r/R)^2$.

In the Poisson model, if $X_e(\eta;r,R)$ is the conditional probability
of any of these specified arm events, then
\begin{equation}\label{eq:arm-second-moment}
 \bigl(\EE X_e(\eta;r,R)^2\bigr)^{1/2}
       \le C\,\PP(\text{the corresponding arm event}).
\end{equation}
At fixed positive radii with $r\le R/2$, the conditional arm probabilities
minus their annealed probabilities converge to zero in probability over
the geometry.  Both assertions apply to the half-plane events just stated.
For triangular four arms one may choose $g\in(5/4,4/3)$.
\end{lemma}

\begin{lemma}[Color order in a rectangle]\label{lem:rectangle-colors}
Let a finite plane graph be drawn in a topological rectangle, with
independent fair colors on its vertices.  The probability of $k$
vertex-disjoint crossings between two opposite sides, with a
specified ordered list of colors, does not depend on that list.
The assertion remains valid after arbitrary vertex deletions.
Uncolored fan terminals on the two target sides may be shared;
disjointness and order are then imposed on the paths and their
incident edges off the fan terminals.
\end{lemma}

\begin{lemma}[Finiteness and the auxiliary pivotal scale]\label{lem:pivotal-scale}
For every mesh, the expected number of color-pivotal sites for $Q_*$
and for
\[
 Q_0=[-1,1]\times[-1/2,1/2]
\]
with left--right target sides is finite and strictly positive.  At
criticality,
\begin{equation}\label{eq:aux-pivotal-scale}
 \EE N_e(Q_0)\asymp m_e A_e(b_e,1).
\end{equation}
Consequently, with
\begin{equation}\label{eq:aux-scale-def}
 a_e=A_e(b_e,1),\qquad q_e=\frac1{\EE N_e(Q_0)},
\end{equation}
we have $q_e\asymp(m_ea_e)^{-1}$ and $q_e\to0$.
\end{lemma}

\begin{lemma}[Sampled target domains determine the curve]
\label{lem:no-hidden-excursions}
Every subsequential limit of the exploration in
Proposition~\ref{prop:chordal} has the law of chordal
$\mathrm{SLE}_6$ as an ordered curve.
\end{lemma}

\begin{proposition}[Uniform bound for the site expansion]
\label{prop:expansion-bound}
Fix a box $B$, finitely many polygonal crossing tests, and $R\leq2$
replica labels.  Let $g\in(1,2)$ be an exponent in the lower four-arm
bound of Lemma~\ref{lem:arm-inputs}.  There is a constant $C$, depending
only on this data, such that, for every $k\geq1$, every choice of
nonempty $I_i$, and centered weights $w_{i,r}$,
\begin{equation}
 \frac{(m_eq_e)^k}{k!}
   \int_{B^k_{\ne}}
       |K_e(F;\mathbf x,\mathbf I,\mathbf w)|
                    \,d\sigma_e^{\otimes k}(\mathbf x)
 \leq C^k k^{-(1-g/2)k}
             \prod_{i,r\in I_i}\|w_{i,r}\|_{\TV},
 \label{eq:coefficient-bound}
\end{equation}
uniformly for all sufficiently small meshes and all $|F|\leq1$ of the
specified crossing indicators.  Consequently the absolute sum in
\eqref{eq:site-expansion} is bounded by
$\sum_{k\geq1}C_T^k k^{-(1-g/2)k}<\infty$ when all times have absolute
value at most $T$.  For two replicas, the total absolute contribution
of terms with $|I_i|=2$ for at least one $i$ is $O_T(q_e)$.
\end{proposition}

\begin{lemma}[Uniform integrability in the insertion locations]
\label{lem:location-ui}
Fix $k$, the polygonal test family, $R\leq2$, and an upper bound on
all the variation norms in~\eqref{eq:site-kernel}.  There are $p>1$ and
$C_k<\infty$ such that, after extending the kernel by zero to coincident
tuples,
\begin{equation}
 \int_{B^k}
   \left|(m_eq_e)^kK_e(F;\mathbf x,\mathbf I,\mathbf w)\right|^p
                      \,d\sigma_e^{\otimes k}(\mathbf x)
                   \leq C_k.
 \label{eq:kernel-lp}
\end{equation}
Let $Z$ be the union of all tested polygon boundaries and $\partial B$.
For $\rho>0$ let $\mathcal B_\rho\subset B^k$ consist of tuples for
which $|x_i-x_j|<\rho$ for some $i\ne j$ or
$\dist(x_i,Z)<\rho$ for some $i$.  Then
\begin{equation}
 \lim_{\rho\downarrow0}\limsup_{e\downarrow0}
    (m_eq_e)^k\int_{\mathcal B_\rho}
       |K_e(F;\mathbf x,\mathbf I,\mathbf w)|
                       \,d\sigma_e^{\otimes k}(\mathbf x)=0.
 \label{eq:location-cutoff}
\end{equation}
The conclusions are uniform in the indicated tests and weights.
They remain true after omitting the geometry cutoff $\Gamma_e$ from
the definition of the kernel.
\end{lemma}

\begin{lemma}[A square can transmit a pivotal change]
\label{lem:disk-lower}
There is $c>0$ such that, for every sufficiently small fixed $h>0$ and all
sufficiently small $e$ depending on $h$,
\begin{equation}
 D_e(h)\geq c a_{e,h}.
 \label{eq:disk-lower}
\end{equation}
The same assertion holds for the one-time square-insertion kernel of a
fixed square or rectangle crossing when its center varies in a sufficiently
small open neighborhood of the center of that test.  The constant is
uniform over that neighborhood.
\end{lemma}

\begin{proposition}[Signed relative replacement]
\label{prop:replacement}
Under the preceding assumptions, fix the types $t_2,\ldots,t_k$ and put
\[
 K_s=K_e^{(s,t_2,\ldots,t_k)}(F;\boldsymbol x,\boldsymbol w),\qquad
 K_d=K_e^{(d,t_2,\ldots,t_k)}(F;\boldsymbol x,\boldsymbol w),\qquad
 P_e=\prod_{i=2}^k \gamma_e(t_i).
\]
The empty product is $1$.  In either model,
\begin{equation}
 \lim_{h\downarrow0}\limsup_{e\downarrow0}
 \sup_{\boldsymbol x}
 \frac{|K_sD_e(h)-K_dS_e|}{P_e a_e a_{e,h}}=0.
 \label{eq:signed-relative-replacement}
\end{equation}
The supremum is over the fixed compact separated range, restricted to
lattice sites in the triangular model; in Poisson insertion integrals,
null general-position exceptions are omitted.  The assertion is uniform
for bounded total variations of the centered weights.
\end{proposition}

\begin{lemma}[One-trial comparison]
\label{lem:one-trial}
For the preceding fixed layouts and tolerances, there is $C_*<\infty$,
independent of the number of trials, their scales, and sufficiently small
mesh, such that
\begin{equation}
 \PP(E\cap N\cap B_J^c)
 \leq C_*\,
 \PP\left(E\cap U_J\cap\bigcap_{I\ne J}U_I^c\right)
 \label{eq:one-trial-comparison}
\end{equation}
for every trial $J$.
\end{lemma}

\begin{lemma}[The prescribed normalization]
\label{lem:square-normalization}
There is a common constant $B\in(0,\infty)$ such that, in each model,
\begin{equation}
 q_e\EE N_e(Q_*)\longrightarrow B,
 \qquad r_e=\frac{q_e}{B+o(1)}.
 \label{eq:square-normalization}
\end{equation}
In particular, both prescribed scales tend to zero.
\end{lemma}

\begin{lemma}[Integer lift]\label{lem:spin-lift}
Every coherent pair on $G$ has an integer Lipschitz lift, unique up to addition
of a multiple of four once the correspondence \eqref{discrete:gray} is fixed.
For the oriented edge $uv$ its increment is
\begin{equation}\label{discrete:increment}
 H_v-H_u=\frac{W_uB_v-B_uW_v}{2}.
\end{equation}
The free spin law induces the weighted height-increment law with one height
anchored. Fixing a constant pair on a connected skeleton, and fixing the lift
there, induces the usual weighted height Gibbs law in each bounded face of
the skeleton.
\end{lemma}

\begin{lemma}[The complementary-spin partition sum]
\label{discrete:ising-partition}
For $a\in[0,1]^E$ define
\begin{equation}\label{discrete:ising-Z}
 Z(a)=\sum_{\sigma\in\{-,+\}^{V}}
             \prod_{e=uv\in E}a_e^{\ind\{\sigma_u\ne\sigma_v\}},
 \qquad 0^0=1.
\end{equation}
Then $Z$ is increasing in every coordinate and is log-supermodular:
\begin{equation}\label{discrete:Z-lattice}
 Z(a\wedge b)Z(a\vee b)\ge Z(a)Z(b).
\end{equation}
\end{lemma}

\begin{lemma}[Geometric tails for shell counts]\label{lem:shell-moments}
In a finite constant-boundary height problem, let $N_d(z)$ be the number
of level loops surrounding a site $z$ whose Euclidean closest approach
to $z$ belongs to $[d,2d)$, where $d\geq1$.  There are $c,C>0$ such that
\begin{equation}\label{moments:shell-tail}
 \Prob\{N_d(z)\geq t\}\leq Ce^{-ct}\qquad(t\geq0).
\end{equation}
In particular, for each finite $p\geq1$, $\E N_d(z)^p\leq C_p$.
These constants are independent of the shape, $z$, and $d$, and the
same assertions hold in any bounded face of a connected flat skeleton.
\end{lemma}

\begin{lemma}[Common loops and the logarithmic covariance bound]
\label{moments:covariance}
Let the flat trace be zero, let $n$ be the distance from $z_0$ to its
bounding skeleton, and let $z,w\in B(z_0,a)$, where
$1\leq a\leq c_0n$ for a sufficiently small absolute $c_0$.  With
$b=\max(1,|z-w|)$,
\begin{equation}\label{moments:covariance-bound}
 0\leq\E[H(z)H(w)]
 \leq C\left(1+\log\frac{n}{b}\right).
\end{equation}
Every smearing~\eqref{moments:weights} in this ball therefore satisfies
\begin{equation}\label{moments:second-moment}
 \E Y^2\leq C A^2\left(1+\log\frac{n}{a}\right).
\end{equation}
\end{lemma}

\begin{lemma}[Admissibility and energy at rounded midpoints]
\label{moments:weighted-midpoints}
Let $\mathcal S$ be the integer $1$-Lipschitz arrays on a finite
connected graph, with fixed integer heights on a nonempty set of
vertices.  Set
\[
 \mathcal W(h)=\ind_{\{h\in\mathcal S\}}
       x^{\sum_{\{i,j\}}|h_i-h_j|}.
\]
Then $\mathcal S$ is finite, both rounded midpoints of $s,t\in\mathcal S$
belong to $\mathcal S$, and
\begin{equation}\label{moments:weight-midpoint}
 \mathcal W(m_-(s,t))\mathcal W(m_+(s,t))\geq \mathcal W(s)\mathcal W(t).
\end{equation}
Moreover a linear statistic with $\sum|w_i|\leq A$ obeys
\begin{equation}\label{moments:rounding}
 \left|Y(m_\pm(s,t))-\frac{Y(s)+Y(t)}2\right|\leq A/2.
\end{equation}
The same energy inequality holds with additional support constraints
whenever both outputs satisfy those constraints.
\end{lemma}

\begin{lemma}[Central mass in finitely many classes]
\label{lem:midpoint-amplification}
Let $\mu(h)=\mathcal W(h)/Z$ be a finite probability measure on integer arrays.
Partition its support into at most $J$ classes.  Suppose that two arrays
from the same class have both rounded midpoints in the full support,
with the weight inequality~\eqref{moments:weight-midpoint}.  Let $Y$ be
a linear statistic satisfying~\eqref{moments:rounding}.  If $M>0$,
$M\geq A/2$, and, for every class $\mathcal S_i$,
\begin{equation}\label{moments:class-central}
 \mu\bigl(\mathcal S_i\cap\{|Y|\leq M\}\bigr)\geq c>0,
\end{equation}
then there are $a_*>0$ and $C_p<\infty$, depending only on $J,c,p$, such
that
\begin{equation}\label{moments:amplification}
 \mu\{|Y|>tM\}\leq4e^{-a_*t}\quad(t\geq0),
 \qquad \|Y\|_{L^p(\mu)}\leq C_pM\quad(1\leq p<\infty).
\end{equation}
Outputs may belong to any class.  In particular no stability of an
individual class under midpoint rounding is required.
\end{lemma}

\begin{proposition}[Uniform plane moments for zero-total smearings]
\label{prop:plane-moments}
For the infinite-volume increment law furnished by
Proposition~\ref{prop:local-mixing}, every zero-total
smearing~\eqref{moments:weights} satisfies
\begin{equation}\label{moments:plane-bound}
 \left\|\sum_uw_uH(u)\right\|_p\leq C_{p,A}
 \qquad(1\leq p<\infty).
\end{equation}
The constants are uniform in $a\geq1$ and the center.  The same estimate
holds for the increment law in a finite free simply connected
triangulation containing $B(z_0,C_0a)$, for a sufficiently large fixed
$C_0$.
\end{proposition}

\begin{lemma}[Nondegeneracy between two disks]\label{lem:nondegeneracy}
Let $U_1,U_2$ be two fixed disjoint round disks with disjoint closures,
and let $f_i\geq0$ be smooth functions supported compactly in $U_i$,
with $\int f_i=1$.  Form their exact face-area averages on the dilated
lattice geometry of scale $R$.  If $Y_R$ is the first average minus
the second, there is $c>0$ such that
\begin{equation}\label{moments:nondegeneracy}
 \E Y_R^2\geq c
\end{equation}
for all sufficiently large $R$, in the plane and in sufficiently large
finite free volumes.  The bound is uniform under translations of the
fixed arrangement.
\end{lemma}

\begin{proposition}[Plane covariance and normalization]
\label{prop:plane-covariance}
There is a constant $v=v(x)\in(0,\infty)$, depending only on the fixed
weight $x$, such that for every pair of real zero-integral tests
$f,g\in C_c^\infty(\R^2)$,
\begin{align}
 \lim_{\delta\downarrow0}\E[H_\delta(f)H_\delta(g)]
 &=\frac{v}{(2\pi)^2}
       \int_{\R^2}\frac{\widehat f(p)\overline{\widehat g(p)}}{|p|^2}
                  \dd p                                      \label{plane:eq:covariance}\\
 &=\frac{v}{2\pi}\iint_{\R^2\times\R^2}
          f(z)\log\frac1{|z-w|}\,g(w)\dd z\dd w.              \notag
\end{align}
The conclusion also holds for zero-integral tests converging in
$C_c^\infty$ with a common compact support.
\end{proposition}

\begin{lemma}[Punctured spectral measure]
\label{plane:lem:spectrum}
There is a positive, locally finite measure $C$ on
$\widehat\T\setminus\{0\}$, invariant under the lattice rotations and
reflections, such that every finitely supported real array $(b_u)$ with
$\sum b_u=0$ satisfies
\begin{equation}
 \label{plane:eq:spectrum}
 \E\left|\sum_u b_uH(u)\right|^2
   =\int\left|\sum_u b_ue^{ip\cdot u}\right|^2 C(\dd p).
\end{equation}
There is no invariant random linear tilt term.  Moreover, for some
$r_0>0$ and $K<\infty$,
\begin{equation}
 \label{plane:eq:annuli}
 C\{r\le|p|\le2r\}\le K\quad(0<r<r_0),
 \qquad
 \int_{0<|p|<r_0}|p|^t C(\dd p)<\infty\quad(t>0).
\end{equation}
\end{lemma}

\begin{lemma}[Positive Cauchy mixture and exceptional sets]
\label{plane:lem:mixture}
On $k\ne0$ in the rectangular torus there is a positive measure
$\nu(\dd k,\dd s)$ such that
\begin{equation}
 \label{plane:eq:mixture}
 C'(\dd k,\dd l)=\int_{[0,\infty]}Q_s(\dd l)\,\nu(\dd k,\dd s).
\end{equation}
The measure $\nu$ is finite on horizontal bands bounded away from zero,
and, for every sufficiently small fixed $\kappa>0$,
\begin{equation}
 \label{plane:eq:weighted-nu}
 \int_{0<|k|<\kappa}|k|\,\nu(\dd k,\dd s)<\infty.
\end{equation}
The physical punctured line $k=0$ near zero has zero $C$ mass, and
$C\{a_*\}=0$.  These conclusions hold before any rescaling limit is taken.
The analogous assertions hold in each of the three rotated charts.
\end{lemma}

\begin{lemma}[Angular identity and summable defect]
\label{plane:lem:defect}
Uniformly for $s\in[0,\infty]$ and sufficiently small $k\ne0$,
\begin{equation}
 \label{plane:eq:poisson}
 \int\chi(k,l)Q_s(\dd l)=D(k,s)+O(|k|).
\end{equation}
For some fixed $\kappa>0$,
\begin{equation}
 \label{plane:eq:defect}
 \int_{0<|k|<\kappa}D(k,s)\,\nu(\dd k,\dd s)<\infty.
\end{equation}
There is also $K_1<\infty$ such that, for all sufficiently small $r>0$,
\begin{equation}
 \label{plane:eq:bands}
 \nu\{r\le|k|\le2r\}\le K_1.
\end{equation}
\end{lemma}

\begin{lemma}[Endcaps]
\label{lem:endcaps}
After decreasing $r_0$ if necessary, there is $K_3<\infty$ such that
\begin{equation}
 \label{plane:eq:endcaps}
 C\{b<|p|\le2b,\ |k|\le h\}\le K_3\frac hb
 \qquad(0<b<r_0,\quad0<h<b/10).
\end{equation}
The same bound holds in each rotated chart.  In particular, rescaling
cannot create mass on one of the tangential zero lines inside a compact
punctured annulus.
\end{lemma}

\begin{lemma}[Form of every subsequential spectrum]
\label{plane:lem:subsequences}
Every vague subsequential limit is
\begin{equation}
 \label{plane:eq:subsequence}
 M(\dd p)=c\frac{\dd p}{|p|^2}
\end{equation}
for some finite $c\ge0$, at this point possibly depending on the
subsequence.  This identity holds on the entire punctured plane,
including the tangential zero lines.
\end{lemma}

\begin{lemma}[A cutoff identity determining the coefficient]
\label{plane:lem:unique}
There is a single $c\ge0$ such that $C_\delta$ converges vaguely to
$c\dd p/|p|^2$ as $\delta\downarrow0$.
\end{lemma}

\begin{lemma}[Bounded label count]\label{pins:label-count}
At fixed $\mathcal L$ and $\epsilon$, the number of connected
components used to form $A_{\delta,\epsilon}$ is bounded by a constant
$M(\mathcal L,\epsilon)$ independent of sufficiently small $\delta$.
\end{lemma}

\begin{lemma}[Integer traces and order]\label{pins:bracket-order}
The bracket traces are actual integer heights satisfying
\begin{equation}\label{pins:trace-intervals}
 H_\delta^{+,\epsilon}\in\{0,1\},\qquad
 H_\delta^{-,\epsilon}\in\{-1,0\}
 \quad\hbox{on }S_{0,\delta},\qquad
 H_\delta^{\pm,\epsilon}=0\quad\hbox{on }A_{\delta,\epsilon}.
\end{equation}
Conditional on either trace, the free interior has the original weighted
height Gibbs law.  There is an ordered coupling
\begin{equation}\label{pins:height-sandwich}
 H_\delta^{-,\epsilon}\le h_\delta\le H_\delta^{+,\epsilon}
\end{equation}
on every interior face.  The bounded-trace smearing estimates of
Proposition~\ref{prop:smearing} apply to both brackets with constants
independent of the window sizes.
\end{lemma}

\begin{lemma}[Marker checks]\label{pins:marker-checks}
For every fixed $a,\epsilon$ and separated placement of the groups,
\begin{equation}\label{pins:check-success}
 \Prob(P_{\mathrm{loc}}\mid P)\longrightarrow1.
\end{equation}
The assertion holds also after any fixed rigid translations or lattice
reflections of the groups, and along converging placements that retain
the specified positive clearances.
\end{lemma}

\begin{lemma}[Normalized side norm]\label{pins:side-norm}
Suppose a family of checked obstacles and factors lies strictly on one
side of a site row.  Their filled neighborhoods and all needed check
paths lie on that side; unbounded factors have free test neighborhoods
disjoint from the obstacle neighborhoods.  If $A$ is a bounded product,
possibly including arbitrary Haar phases, times at most one smooth
zero-total insertion, then
\begin{equation}\label{pins:normalized-side-bound}
 \left\|A\prod_i\frac{\ind_{P_i\cap C_i}}{p_{i,\delta}}
       \right\|_\vartheta\le C.
\end{equation}
The bound is uniform on compact families with the stated margins.
\end{lemma}

\begin{lemma}[Separated insertion]\label{pins:three-moves}
At fixed positive gaps satisfying \eqref{pins:middle-geometry}, and for
any product $\Psi_\delta$ of local Haar-phase factors at the
representatives with fixed frequencies,
\begin{equation}\label{pins:separated-identity}
 J_\delta^{-1}\E\left[
 X_\delta F_\delta\Psi_\delta\ind_{P_{\mathrm{loc}}}\right]
 \longrightarrow0.
\end{equation}
This holds for every converging lattice-rounded sequence of placements
with the stated strict separations.
\end{lemma}

\begin{lemma}[Gap closing]\label{pins:gap-closing}
There is a function $\omega(a)\to0$ as $a\downarrow0$ such that
\begin{align}
 \limsup_{\delta\downarrow0}
       \Prob(P_=^c\mid P)&\le\omega(a),
       \label{pins:offset-synchronization}\\
 \limsup_{\delta\downarrow0}
 \left\|\mu_{\delta,a}^{=}|_{\mathcal I_\delta}
              -\mu_{\delta,0}|_{\mathcal I_\delta}\right\|_{\TV}
       &\le\omega(a),\label{pins:increment-tv}\\
 \limsup_{\delta\downarrow0}
       \E_{\mu_{\delta,a}^{=}}|X_\delta|^p
       &\le C_p\qquad(1\le p<\infty),
       \label{pins:uniform-common-moments}
\end{align}
where $\mathcal I_\delta$ is the joint increment information in the
fixed test disks.  The constants in the last line are independent of
all sufficiently small $a$.
\end{lemma}

\begin{proposition}[Vanishing bracket means]
\label{prop:bracket-collapse}
Fix a finite regular grid as in Definition~\ref{def:brackets}.
For every $f\in C_c^\infty(D)$, the upper and lower bracket fields
satisfy
\begin{equation}
 \lim_{\epsilon\downarrow0}\ \limsup_{\delta\downarrow0}
 \left|\E H_\delta^{\pm,\epsilon}(f)\right|=0.
 \label{boundary:bracket-means}
\end{equation}
\end{proposition}

\begin{lemma}[Transfer to the chosen field]
\label{limit:transfer}
The field \(H\) satisfies the limiting insertion identity of
Proposition~\ref{prop:bracket-insertion} in every disk arrangement
allowed there:
\begin{equation}
 \E\left[H(\Delta\varphi)
          \prod_{\ell=1}^k H(g_\ell)\right]=0,
 \qquad \int g_\ell=0,
 \label{eq:limit-insertion}
\end{equation}
where each \(g_\ell\) is supported in its indicated spectator disk.
The same assertion first holds with each spectator replaced by a
bounded continuous function of finitely many zero-total tests in that
disk.
\end{lemma}

\begin{lemma}[No distributions supported on collisions]
\label{lem:no-diagonal}
On every compact subset of \(D^j\), the off-diagonal function from
Proposition~\ref{prop:harmonic-moments} is locally integrable and
represents all of \(T_j\).  For \(j\ge2\), if
\(d(\mathbf z)=\min_{i<k}|z_i-z_k|\), then, locally away from
the boundary,
\begin{equation}
 |T_j(\mathbf z)|
 \le C\bigl(1+\log_+(1/d(\mathbf z))\bigr)^{j/2},
 \qquad \mathbf z\in\mathcal C_j.
 \label{eq:limit-log-bound}
\end{equation}
Moreover, for distinct fixed \(z_2,\ldots,z_j\in D\),
\begin{equation}
 T_j(z_1,z_2,\ldots,z_j)\longrightarrow0
        \quad\text{as }z_1\longrightarrow p\in\partial D.
 \label{eq:limit-zero-boundary}
\end{equation}
\end{lemma}

\begin{proposition}[Collision coefficient]
\label{prop:collision}
In \eqref{eq:limit-puncture},
\begin{equation}
              L(y,\mathbf z)=\frac{v}{2\pi}T_{j-2}(\mathbf z).
 \label{eq:limit-collision}
\end{equation}
The convention \(T_0=1\) applies when \(j=2\).
\end{proposition}

\begin{theorem}[Moment identification and the full field law]
\label{thm:wick}
For every \(j\ge2\) and distinct \(x,y_2,\ldots,y_j\in D\),
\begin{equation}
 T_j(x,y_2,\ldots,y_j)
   =v\sum_{i=2}^j G_D(x,y_i)\,
          T_{j-2}(y_2,\ldots,\widehat{y_i},\ldots,y_j).
 \label{eq:limit-wick}
\end{equation}
Together with \(T_0=1\) and \(T_1=0\), this identifies every moment
distribution with that of \(\sqrt v\,\Phi_D\).
Every subsequential field limit has that law.  Consequently
\(h_\delta/\sqrt v\) converges to \(\Phi_D\) as a random
distribution, with joint convergence of every finite collection of
smooth compactly supported pairings.
\end{theorem}

\begin{lemma}[One complementary-color cut]\label{annulus:one-white}
The comparison of Lemma~\ref{annulus:ambient} for $B$ and signed
$B$ statuses remains valid with one prescribed open $W$ winding contour
of fixed sign, provided that its cells are disjoint from the selected
$B$ cells. Histories still observe no other $W$ labels.
\end{lemma}

\begin{lemma}[Boundary slides]\label{annulus:slide}
Let $\mu_{a,b}$ be the law between a lower open-minus $B$ contour $a$
and an upper open-plus $B$ contour $b$. If the contours are ordered
from bottom to top as
\[
 a_1<a_0<\operatorname{supp}(A)<b_1<b_0,
\]
where $A$ is an increasing $B$ and signed-status event, then
\begin{equation}\label{annulus:slide-cuts}
 \mu_{a_0,b_0}(A)\le \mu_{a_1,b_1}(A).
\end{equation}
Old and new contours may use different classes, with edge-disjoint cells.
In particular, writing $\tau_d A_T$ for the upward translate by $d$ of
an increasing class-$T$ test, for $S,T\in\{Y,Z\}$ we have
\begin{equation}\label{annulus:slide-tests}
 P_S(A_T)\le P_T(\tau_d A_T),
\end{equation}
whenever the downward-translated class-$T$ boundary contours have the
required clearance from the original class-$S$ contours and the test.

Above a fixed open $W$ contour $\gamma$, let $\nu_{\gamma,b}$ denote
the law with upper open-plus $B$ contour $b$. For
$\gamma<\operatorname{supp}(A)<b_0<b_1$, the reverse slide gives
\begin{equation}\label{annulus:slide-white}
 \nu_{\gamma,b_1}(A)\le\nu_{\gamma,b_0}(A).
\end{equation}
\end{lemma}

\begin{lemma}[Winding from the matching seed]\label{annulus:winding}
Under $P_Z$, the horizontal seed above implies a positive lower bound
for an occupied $B$-plus winding of class $Z$ in a thin neighborhood of
height $.71H$, entirely below $.73H$.  The bound is uniform in $n$.
\end{lemma}

\begin{proposition}[The mixed-cylinder seed estimate]
\label{annulus:seed}
For every fixed $C\geq3$ there is $\delta=\delta(x,C)>0$ such that,
for all sufficiently large $n$,
\begin{equation}\label{annulus:seed-bound}
 P_Y\bigl(\mathsf H_Y^+([-2n,2n]\times[3n,4n])\bigr)\geq\delta
\end{equation}
on the mixed cylinder $\mathrm{Cyl}_{Cn,5n}$ of
\cite[Appendix~A]{GL2025}, with the same lattice rounding convention.
\end{proposition}

