\begin{lemma}[Finite Bethe data]\label{lem:bethe-data}
Let $L$ be even, $b_j$ real, and $0<\lambda<\pi$.
A real solution of \eqref{eq:consecutive-counting} satisfies
\eqref{eq:bethe-equations}.  If its Bethe vector is nonzero, then
$|Y\rangle$ is an eigenvector of
$e^{it}\mathsf A(x)+e^{-it}\mathsf L(x)$ with eigenvalue
$\tau_t(x;Y)$, and $\mathcal P_L|Y\rangle$ is an eigenvector of the
physical twisted row with eigenvalue $(-1)^n\tau_t(x;Y)$.
The Jacobian of \eqref{eq:consecutive-counting} is
\begin{equation}\label{eq:Gaudin-matrix}
 G_{jk}=\xi_Y'(y_j)\delta_{jk}+K(y_j-y_k),\qquad
 \xi_Y'(u)=\sum_{a=0}^{L-1}s(u-b_a)-\sum_{k=1}^nK(u-y_k).
\end{equation}
If $\det G\ne0$, the roots have a real analytic continuation for real
$t$ near the given value, and on that branch
\begin{equation}\label{eq:twist-root-derivative}
 G\frac{\dd Y}{\dd t}=\frac1\pi\bbone.
\end{equation}
For $\lambda\ge\pi/2$, $G$ is positive definite at every real root
list.  Whenever $\xi_Y'(y_j)>0$, write
\begin{equation}\label{eq:Gaudin-weights}
 \ell_j=\frac1{\xi_Y'(y_j)},\qquad
 (K\ell)_{jk}=K(y_j-y_k)\ell_k;
 \qquad G\diag(\ell)=I+K\ell.
\end{equation}
These assertions concern finite matrices; they give no uniform bound on
$(I+K\ell)^{-1}$ as $L$ increases.
\end{lemma}

\begin{lemma}[Exact scalar products and deleted columns]
\label{lem:scalar-product}
In the normalization \eqref{eq:standard-monodromy},
\begin{equation}\label{eq:Slavnov-exact}
 S(Y,U)=e^{-int}\left(\prod_{y\in Y}l(y)\right)
 \frac{\det_{j,k}\partial_{y_j}\tau_t(U_k;Y)}
      {\det C(Y,U)}.
\end{equation}
Consequently, if $\det G_Y\ne0$, then $S(Y,Y)\ne0$ and
\begin{equation}\label{eq:Gaudin-norm-exact}
 S(Y,Y)=(2\pi i s_\lambda)^n
       \left(\prod_{y\in Y}a(y)l(y)\right)
       \left(\prod_{j\ne k}f(y_j-y_k)\right)\det G_Y.
\end{equation}
Suppose $U$ is obtained by replacing the roots indexed by
$H=(p_1,\ldots,p_k)$ by $V=(v'_1,\ldots,v'_k)$, in those same slots.
Set
\[
 A_Y(p)=a(p)\prod_{y\in Y\setminus\{p\}}f(y-p)\quad(p\in Y).
\]
Then the normalized scalar product is exactly
\begin{equation}\label{eq:deleted-scalar-product}
 \frac{S(Y,U)}{S(Y,Y)}
 =(-s_\lambda)^{-k}
   \frac{\prod_{v'\in V}a(v')F_Y(v')}{\prod_{p\in H}A_Y(p)}
   \frac{\det\bigl((G_Y^{-1}m_{v'}^t)_p\bigr)_{H,V}}
        {\det\bigl(1/[v'-p]\bigr)_{H,V}}.
\end{equation}
If the positive weights \eqref{eq:Gaudin-weights} are defined, the
last numerator equals
\begin{equation}\label{eq:W-determinant}
 \det\bigl((G_Y^{-1}m_{v'}^t)_p\bigr)_{H,V}
 =\left(\prod_{p\in H}\ell_p\right)
       \det\bigl(W_{v'}(p)\bigr)_{H,V},
 \qquad W_{v'}=(I+K\ell)^{-1}m_{v'}^t.
\end{equation}
Empty products and determinants have value one.
\end{lemma}

\begin{lemma}[The Hilbert dual]\label{lem:hilbert-dual}
For even $L$ and real inhomogeneities,
\begin{equation}\label{eq:B-Hilbert-adjoint}
 \mathsf B(x)^*=-\mathsf C(\bar x).
\end{equation}
Thus for a distinct real on-shell list with $\det G_Y\ne0$, the
physical unit vector
\begin{equation}\label{eq:physical-Bethe-vector}
 \Omega_Y=\frac{\mathcal P_L|Y\rangle}{\|\mathcal P_L|Y\rangle\|}
\end{equation}
is well defined, and
\[
 \|\mathcal P_L|Y\rangle\|^2=(-1)^nS(Y,Y)>0.
\]
If $Y,Z$ are two such real on-shell lists of the same size, possibly
for different twists, then
\begin{equation}\label{eq:two-orientation-overlap}
 |\langle\Omega_Y,\Omega_Z\rangle|^2
       =\frac{S(Y,Z)S(Z,Y)}{S(Y,Y)S(Z,Z)}.
\end{equation}
These identities also hold for real staggered $b_j$, without a Perron
interpretation of the vectors.
\end{lemma}

\begin{corollary}[Exact finite-word expansion]\label{cor:finite-word-expansion}
Expand each auxiliary mark as
\[
 T^{D_j}=\sum_{\alpha,\beta}(D_j)_{\beta\alpha}
 M_{{\rm ph},\alpha\beta}.
\]
For each resulting entry word, let $n_j$
be the number of minus spins after its $j$th action, with $n_0=n$.
Entry words with $n_m\ne n$ have zero expectation in $\Omega_Y$.
For a path of a word with $n_m=n$, let $H\subset Y$ be the roots
absent at the end and let $V$ be its surviving added arguments, ordered
in the same replacement slots.  Then $|H|=|V|=:k\le m$, and its
contribution to the normalized physical expectation is
\begin{equation}\label{eq:exact-path-determinant}
 \left(\prod_{j=1}^m(D_j)_{\beta_j\alpha_j}\right)
 (-1)^{\sum_{j=1}^m(n_{j-1}-n)}
 (-s_\lambda)^{-k}
 \frac{\prod_{j=1}^m\gamma_j}
      {\prod_{j=1}^m(1+q_Y(v'_j))}
 \frac{\det(W_{v'}(p))_{H,V}}
      {\det(1/[v'-p])_{H,V}}
 \prod_{p\in H}\ell_p.
\end{equation}
The expectation is the sum of these contributions.  In particular,
the determinant size is bounded by the word length.  For diagonal
entry words the parity sign in \eqref{eq:exact-path-determinant} is
one.  Among distinct removed original roots the correction product
contains only reciprocal $f$ factors, with one for each pair.  Each
removed original root also contributes one factor $\beta$ joining it
to the row argument at the step that removes it.
\end{corollary}

\begin{lemma}[Harmonic row normalization]\label{lem:row-normalization}
There is a real harmonic function $U$ on $\mathcal S_\lambda$
such that, for every finite real-inhomogeneity chain,
\begin{equation}\label{eq:harmonic-row-bound}
 \|T^D(x)\|\le2\|D\|
                 \exp\left(\sum_jU(x-b_j)\right).
\end{equation}
Choose a nonvanishing analytic function $\mathcal N_L$ whose
modulus is the exponential on the right.  In the homogeneous plane
and array limits, the untwisted vacuum eigenvalue $\tau_L$ satisfies
\begin{equation}\label{eq:vacuum-modulus-normalization}
 |\tau_L(x)/\mathcal N_L(x)|\longrightarrow1
\end{equation}
locally uniformly in the strip, with the moving-bulk convention
\eqref{eq:array-limit-convention} in the array case.
Consequently, for each compact $\mathcal K\subset\mathcal S_\lambda$,
\begin{equation}\label{eq:normalized-row-bound}
 \limsup\sup_{x\in\mathcal K}\|A_L^D(x)\|\le2\|D\|.
\end{equation}
In particular the vacuum denominator has no zeros on such a compact
for all sufficiently large systems in the indicated sense.
\end{lemma}

\begin{lemma}[Inner spectra and the current measure]\label{lem:inner-spectra}
On $\mathcal D$, almost every spectral function is either $1$ or a
finite Blaschke product in the right half-plane, with
\begin{equation}\label{eq:finite-inner-symmetry}
 f(0)=f(\infty)=1,\qquad
 f(\overline w)=\overline{f(w)}.
\end{equation}
Its zeros obey \eqref{eq:angular-cone}.  In particular its degree is
even; write it as $2n_f$ when it is nonconstant.  Every zero produces
a fixed-width, fixed-depth dip of $|f(e^s)|$ near its logarithmic radius.

There is a possibly infinite positive measure $\mu$ on the nonconstant
functions and a measurable spectral vector $\mathsf h$ such that
\begin{equation}\label{eq:current-cocycle}
 J(w)\Omega=(1-f(w))\mathsf h,
 \qquad \mu(\dd f)=\|\mathsf h(f)\|^2\,\sigma(\dd f).
\end{equation}
Here $\sigma$ is any scalar measure used for the direct-integral
representation; the resulting measure $\mu$ does not depend on that
choice.  It is invariant under dilation of the argument.  On the
cross-section where the smallest zero radius is one, it has the form
\begin{equation}\label{eq:orbit-disintegration}
 \mu=\dd s\,\nu(\dd F),\qquad f(w)=F(e^s w),\qquad
 \kappa:=\nu(1)<\infty.
\end{equation}
If $\mathcal L(F)$ is the difference between its largest and smallest
logarithmic zero radii, then
\begin{equation}\label{eq:orbit-width-tail}
 \nu\{\mathcal L>t\}\le Ce^{-2\eta t}\quad(t\ge1).
\end{equation}
For a fixed diagonal word $h$,
\begin{equation}\label{eq:diagonal-boost-tail}
 \|(1-P(e^s))h\|\le C_h e^{-\eta|s|}.
\end{equation}
For products of fixed words placed at scales $r_i$, the corresponding
bound outside their fixed internal argument ranges is
$C\sum_i e^{-\eta|s-\log r_i|}$, uniformly when these ranges separate.
\end{lemma}

\begin{lemma}[The local endpoint generator]\label{lem:endpoint-Hamiltonian}
The nonnegative self-adjoint spectral operator
\begin{equation}\label{eq:angular-endpoint-energy}
 E=S^{-1}\partial_zP(z)\big|_{z=v},\qquad
 E(f)=-\left.\partial_s\arg f(ie^s)\right|_{s=0},
\end{equation}
agrees on local-spin vectors with the vacuum-subtracted nearest-neighbor
Hamiltonian whose link is
\begin{equation}\label{eq:angular-local-link}
 h_{j,j+1}=-\eta\,\operatorname{swap}_{j,j+1}R'_{j,j+1}(0)
 =\begin{pmatrix}
 \eta\cot\lambda&0&0&0\\
 0&0&-\eta/\sin\lambda&0\\
 0&-\eta/\sin\lambda&0&0\\
 0&0&0&\eta\cot\lambda
 \end{pmatrix}_{j,j+1}.
\end{equation}
In particular $[h_{j,j+1},Z_j+Z_{j+1}]=0$ and $E\Omega=0$.
The closure of the local-spin subspace reduces $E$, and its real-time
evolution is the local Hamiltonian evolution.  For all sufficiently
small $u$,
\begin{equation}\label{eq:angular-E-H-comparison}
 \bbone_{\{E\le u\}}\le\bbone_{\{H_0\le Cu\}}.
\end{equation}
With $Z_1=S^{-1}Z_0S$, the exact adjacent-pair identity is
\begin{equation}\label{eq:angular-adjacent-current}
 N(i)=\tfrac12 S^2(Z_0+Z_1).
\end{equation}
\end{lemma}

\begin{lemma}[Energy and winding sum rule]\label{lem:sum-rule}
Let $p$ denote the phase of the unit shift $S=P(i)$, modulo $2\pi$, and
let $\operatorname{sym}$ average a measure at $p$ and $-p$.  Set
\[
 D_0=-\langle\Omega,[Z_0,[Z_0,h_{0,1}]]\Omega\rangle.
\]
Away from $p=0$, the projection of the current measure obeys
\begin{equation}\label{eq:angular-sum-rule}
 2\operatorname{sym}\bigl((p)_*(E\mu)\bigr)
       =D_0\frac{\dd p}{2\pi}.
\end{equation}
On each orbit of degree $2n_F$, the phase winds monotonically through
$n_F$ complete turns.  In particular
\begin{equation}\label{eq:angular-degree-integral}
 \int n_F\dd\nu(F)<\infty.
\end{equation}
\end{lemma}

\begin{proposition}[Exact variogram and logarithmic growth]
\label{prop:variogram}
After an axial symmetry, any nonzero lattice displacement may be
written $(k,j)$ with $k\ge1$ and $|j|\le k$.  Its height variance is
\begin{equation}\label{eq:angular-variogram}
 \begin{aligned}
 \E_c\bigl(h(k,j)-h(0,0)\bigr)^2
 &=2\Re\int\bigl(1-f(1)^k f(\pm i)^{|j|}\bigr)\dd\mu(f)\\
 &=4\kappa\log k+O(1),
 \end{aligned}
\end{equation}
where the sign of $i$ is chosen according to the vertical direction.
The error is uniform over these displacements.  In particular the
variance is bounded by $C(1+\log(1+|k|+|j|))$.
\end{proposition}

\begin{proposition}[The covariance constant below one]\label{prop:normalization}
With the row and height conventions of Sections~\ref{sec:finite}
and~\ref{sec:angular},
\begin{equation}\label{eq:kappa-value}
 \kappa=\frac1{2\pi(\pi-\lambda)}.
\end{equation}
Consequently a limiting covariance \(-2\kappa\log|x-y|\) has squared
multiplier \(4\pi\kappa=2/(\pi-\lambda)=\sigma(c)^2\) relative to
\eqref{eq:green}.
\end{proposition}

\begin{lemma}[Homogeneous stiffness]\label{lem:stiffness}
The iterated homogeneous stiffness satisfies
\begin{equation}\label{eq:stiffness-value}
 \lim_{Q\to\infty}\lim_{L\to\infty}L e_L''(0)
      =\frac2{\pi-\lambda}.
\end{equation}
\end{lemma}

\begin{lemma}[Infrared comparison]\label{lem:infrared}
With \(\kappa\) as in Section~\ref{sec:angular},
\begin{equation}\label{eq:kappa-lower}
 \kappa\ge\frac1{2\pi(\pi-\lambda)}.
\end{equation}
\end{lemma}

\begin{lemma}[Staggered overlap asymptotic]\label{lem:overlap-asymptotic}
In the order \(B\to\infty\), then \(d\downarrow0\),
\begin{equation}\label{eq:overlap-density}
 \frac{I_L}{B}\longrightarrow\frac1{2\lambda(\pi-\lambda)}.
\end{equation}
The limit is understood in the double-limit convention
\eqref{eq:array-limit-convention}.
\end{lemma}

\begin{lemma}[Packing angular windows]\label{lem:detector-packing}
The plane orbit mass satisfies
\begin{equation}\label{eq:kappa-upper}
 \kappa\le\frac{\eta}{2\lambda(\pi-\lambda)}.
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:chiral-forms}
There are consistent skew-adjoint forms $j_\pm$ on
$\mathcal D_\pm^{\mathrm{fin}}$ such that, for every $R>0$,
\begin{equation}\label{eq:chiral-form-bound}
 \|E_\pm(R)j_\pm E_\pm(R)\|\le CR,
 \qquad E_\pm(R)j_\pm\Omega=E_\pm(R)a_\pm\mathsf h.
\end{equation}
Their vacuum means vanish. For $s>0$, the damped forms extend to bounded
operators and satisfy
\begin{equation}\label{eq:chiral-damped-form}
                     \|e^{-sa_\pm}j_\pm e^{-sa_\pm}\|\le C/s.
\end{equation}
For every nonnegative measurable function $g$ on $(0,\infty)$,
\begin{equation}\label{eq:chiral-Haar-integral}
             \int g(a_\pm(f))\dd\mu(f)
                     =\kappa\int_0^\infty g(t)\frac{dt}{t}.
\end{equation}
\end{lemma}

\begin{proposition}[Two-scale spectral limit]\label{prop:two-scale}
Take $r_1=\delta^{-1}$ and $r_2=\delta$, with $\delta\downarrow0$ through
arbitrary positive real values. On core representatives, the joint spectral
functions $(f(\delta^{-1}\,\cdot),f(\delta\,\cdot))$ converge in law in
the compact-open topology of the right half-plane to the two tensor-factor
functions $(F_1,F_2)$. Jointly with these functions,
\begin{equation}\label{eq:chiral-scaled-spectrum}
\begin{split}
 \delta^{-1}H_0&\longrightarrow A:=a_+\otimes I+I\otimes a_-,\\
 \delta^{-1}\arg S&\longrightarrow -a_+\otimes I+I\otimes a_-,
       \qquad \sgn P(1)\longrightarrow I
\end{split}
\end{equation}
in spectral law. The argument is the principal argument near zero.
There is an unbounded set of $R>0$ for which
\begin{equation}\label{eq:chiral-band-limit}
 Q_\delta(R):=\bbone_{H_0/\delta\le R}
                       \longrightarrow Q(R):=\bbone_{A\le R}
\end{equation}
strongly on representatives. Bounded spectral multipliers obtained jointly
from these limits have the same strong interpretation whenever their
discontinuity sets have zero limiting state mass.

If $m_\delta\ge0$ and $l_\delta$ are integers with
$\delta m_\delta\to x\ge0$ and $\delta l_\delta\to y$, then
\begin{equation}\label{eq:chiral-semigroup-limit}
 P(1)^{m_\delta}S^{l_\delta}\longrightarrow
       e^{-(x+iy)a_+}\otimes e^{-(x-iy)a_-}
\end{equation}
strongly on representatives.
\end{proposition}

\begin{lemma}\label{lem:collision}
For $a=a_+$ and $j=j_+$, the bounded operators
\begin{equation}\label{eq:chiral-collision-operator}
 K_\epsilon=e^{-\epsilon a}(\epsilon j)e^{-\epsilon a}
                      (\epsilon j)e^{-\epsilon a}
\end{equation}
are uniformly bounded for $\epsilon>0$ and satisfy
\begin{equation}\label{eq:chiral-collision-limit}
                    K_\epsilon\rightharpoonup-\kappa I
                       \qquad(\epsilon\downarrow0).
\end{equation}
Consequently, fix $z_2,\ldots,z_k$ with pairwise distinct real
coordinates and pairwise distinct imaginary coordinates, and let
$2\le j\le k$. Then
\begin{equation}\label{eq:chiral-double-pole}
 \lim_{\epsilon\downarrow0}\epsilon^2
 F_k(z_j+\epsilon,z_2,\ldots,z_k)
   =-\kappa F_{k-2}(z_2,\ldots,\widehat z_j,\ldots,z_k).
\end{equation}
The coefficient on the right is independent of both colliding positions.
\end{lemma}

\begin{proposition}\label{prop:gaussian-currents}
Let $k\ge1$, and let $z_1,\ldots,z_k$ have pairwise distinct real
coordinates or pairwise distinct imaginary coordinates. For
$\varepsilon_i\in\{+,-\}$ and moving mesh faces $z_{i,\delta}\to z_i$,
\begin{equation}\label{eq:chiral-Gaussian-current-limit}
 \lim_{\delta\downarrow0}
 \E\prod_{i=1}^k
       \delta^{-1}D_\delta^{\varepsilon_i}h_\delta(z_{i,\delta})
   =\sum_{\pi}\ \prod_{\{i,j\}\in\pi}
                  C_{\varepsilon_i,\varepsilon_j}(z_i,z_j),
\end{equation}
where the sum is over pairings, is zero for odd $k$, and
\begin{equation}\label{eq:chiral-contractions}
 C_{++}(z,\xi)=-\frac{\kappa}{(z-\xi)^2},\qquad
 C_{--}(z,\xi)=-\frac{\kappa}{(\bar z-\bar\xi)^2},\qquad
 C_{+-}(z,\xi)=C_{-+}(z,\xi)=0.
\end{equation}
Convergence is uniform on compact subsets of either separated-time
region. By linearity the corresponding assertion holds for all products
of the real centered derivatives $\delta^{-1}D_{x,\delta}$ and
$\delta^{-1}D_{y,\delta}$. These are the off-diagonal derivatives of the
Gaussian covariance
\begin{equation}\label{eq:chiral-log-covariance}
                              K_\kappa(z,\xi)=-2\kappa\log|z-\xi|.
\end{equation}
\end{proposition}

\begin{lemma}[Ordinary spatial moments]\label{lem:ordinary-moments}
Fix \(0<A<\infty\). Let \(R\ge1\), and let \(g=(g_l)_{l\in\Z}\) be a
finitely supported real sequence such that
\begin{equation}\label{eq:prob-g-conditions}
 \sum_l|g_l|\le AR,\qquad
 \sum_l|g_{l+1}-g_l|\le A,\qquad
 \sum_l|g_{l+1}-g_l|^2\le A/R.
\end{equation}
Then, for every \(1\le b<\infty\),
\begin{equation}\label{eq:prob-ordinary-moments}
 \left\|\sum_lg_lZ_l\right\|_{L^b(\P_c)}\le C_{A,b}.
\end{equation}
In particular the conclusion holds if \(g\) has support of length at
most \(AR\), \(|g_l|\le A\), and
\(|g_{l+1}-g_l|\le A/R\). The same assertions hold with the two axes
interchanged.
\end{lemma}

\begin{corollary}[Neutral blocks]\label{cor:neutral-blocks}
Let \(b\in\R^2\), \(r>0\), and let \(f\) be a measurable real density
supported in a square of side \(Ar\) centered within distance \(Ar\)
of \(b\), with
\[
 \int f=0,\qquad |f|\le A r^{-2}.
\]
For every finite \(q\),
\begin{equation}\label{eq:prob-neutral-block}
 \|\langle h_\delta,f\rangle\|_{L^q}\le C_{A,q}
\end{equation}
uniformly in \(b,r,\delta\). Products of finitely many such blocks have
uniform absolute moment bounds, even when their supports overlap.
\end{corollary}

\begin{proposition}\label{prop:offdiagonal}
For every \(k\ge1\), all \(k\)-point height-increment moments converge
to the Wick increment moments of \(\mathcal H_\kappa\), uniformly on
compact sets of tuples whose endpoint sets belonging to different
increments are disjoint.
\end{proposition}

\begin{lemma}\label{lem:log-integrability}
Let \(\mu\) be a compactly supported finite signed measure for which
\(\iint G(x,y)\,\mu(dx)\mu(dy)\) is an ordinary finite signed-measure
integral. Then \(\mu\) has no atoms, and
\begin{equation}\label{eq:prob-absolute-energy}
 \iint\log_+\frac1{|x-y|}\,|\mu|(dx)|\mu|(dy)<\infty.
\end{equation}
If \(\mu,\nu\) both satisfy this assumption, the corresponding mixed
absolute logarithmic integral is finite as well.
\end{lemma}

\begin{lemma}[Pinned averages]\label{lem:pinned-averages}
Let \(0<\ell\le1\), and let \(\psi_{b,\ell}\) be supported in a square
of side \(A\ell\) about \(b\), with
\(|\psi_{b,\ell}|\le A\ell^{-2}\). For centers \(b\) in a fixed compact
set and every finite \(q\),
\begin{equation}\label{eq:prob-pinned-averages}
 \|\langle X_\delta^\chi,\psi_{b,\ell}\rangle\|_{L^q}
 \le C_{A,q,\chi,\rho}(1+|\log\ell|).
\end{equation}
The estimate is uniform in \(\delta>0\).
\end{lemma}

\begin{lemma}[Averages on small-area cells]\label{lem:cell-averages}
Let \(Q\) be a square of side \(0<\ell\le1\) in a fixed bounded box,
and let \(A\subset Q\) be measurable with \(|A|>0\). Put
\(t=|A|/\ell^2\). Then for every finite \(b\),
\begin{equation}\label{eq:prob-cell-average}
 \left\|\frac1{|A|}\int_A X_\delta(x)\,dx\right\|_{L^b}
 \le C_b(1+|\log\ell|+|\log t|)
\end{equation}
uniformly in \(\delta\) and in the shape of \(A\).
\end{lemma}

\begin{theorem}[Isometry invariance of the endpoint correlations]
\label{thm:rr-rotation}
For every even $k\ge2$ and every compact $K\subset\mathcal D_k$,
\begin{equation}
 \lim_{\delta\downarrow0}
 \sup_{\boldsymbol u\in K}\sup_{I\in\operatorname{Isom}(\R^2)}
 \left|\Phi_{k,\delta}(\boldsymbol u)
             -\Phi_{k,\delta}(I\boldsymbol u)\right|=0.
 \label{eq:rr-target}
\end{equation}
\end{theorem}

\begin{lemma}[Counts, escape, and deterministic-point avoidance]
\label{lem:rr-estimates}
Let $N(a,M)$ be the number of loops of diameter at least $a$ meeting
$B(0,M)$.  For $\delta$ sufficiently smaller than $a$, and every
fixed $p<\infty$,
\begin{equation}
 \|N(a,M)\|_{L^p}\le C_p(1+M/a)^2.
 \label{eq:rr-count}
\end{equation}
There are $C,\gamma>0$ such that, with harmless fixed changes of the
radii,
\begin{align}
 \mathbb P\{\exists L:L\cap B(0,M)\ne\varnothing,
                            L\not\subset B(0,R)\}
      &\le C(M/R)^\gamma, && R\ge10M,
       \label{eq:rr-escape}\\
 \mathbb P\{\exists L:\diam L\ge a,
                       \dist(z,L)\le r\}
      &\le C\bigl((r+C\delta)/a\bigr)^\gamma,
          &&0<r<a/100.
       \label{eq:rr-point}
\end{align}
The constants are independent of the deterministic center $z$.
\end{lemma}

\begin{proposition}[Completion at the endpoint]
\label{prop:endpoint-completion}
The conclusions of Theorem~\ref{thm:main} hold at $c=2$, with squared
multiplier $2/\pi$.
\end{proposition}

\begin{proposition}[Identification of the driver]
\label{cal:driver}
The subsequential driving process is a continuous semimartingale and,
in the above joint filtration, satisfies
\begin{equation}
 \dd W_t=\sqrt{\frac{16}{3}}\,\dd B_t+
                \frac{2\pi}{3}C_t\,\dd t,
 \qquad
 \int_0^T C_t^2\,\dd t<\infty\quad\text{almost surely for every }T<\infty,
 \label{cal:driver-equation}
\end{equation}
where $B$ is a Brownian motion and
\begin{equation}
 C_t=\frac4\pi\int_{\Hh}P(v)\mu_t(v)
              |\nabla(h_t\circ\psi_t)(v)|\,\dd A(v).
 \label{cal:C-definition}
\end{equation}
In particular, neither absolute continuity of the quadratic variation
nor absolute continuity of the finite-variation part of $W$ is an
assumption of the argument.
\end{proposition}

\begin{lemma}[Potential representation and bulk bound]
\label{cal:potential}
There is a constant $K$, depending only on $m$ and a physical diameter
bound, such that on every active domain
\begin{align}
 h_t(z)&=u_t(z)+4m\int_{O_t}G_t(z,w)|M_t(w)|^2\,\dd A(w),
 \label{cal:representation}\\
 |M_t(w)|^2&\leq \frac{K}{\operatorname{crad}_{O_t}(w)}.
 \label{cal:bulk-bound}
\end{align}
In particular the nonnegative potential
\begin{equation}
 Q_t(z):=\int_{O_t}G_t(z,w)|M_t(w)|^2\,\dd A(w)
 \quad\text{satisfies}\quad 0\leq Q_t(z)\leq\frac1{4m}.
 \label{cal:bounded-potential}
\end{equation}
\end{lemma}

\begin{lemma}[Stochastic Green potential]
\label{cal:stochastic-potential}
On every such stopped interval $[0,T]$,
\begin{equation}
 \mathbb E\int_0^T\int_{O_t}G_t(z,w)
                         \,\dd[M(w),\overline{M(w)}]_t\,\dd A(w)<\infty.
 \label{cal:weighted-bracket}
\end{equation}
The potential $Q_t(z)$ has a continuous semimartingale version, and
\begin{align}
 \dd Q_t(z)={}&-\frac2\pi P_t(z)
       \left(\int_{O_t}P_t(w)|M_t(w)|^2\,\dd A(w)\right)\dd t
 \notag\\
 &+\int_{O_t}G_t(z,w)\,\dd[M(w),\overline{M(w)}]_t\,\dd A(w)
 \notag\\
 &+2\operatorname{Re}\int_{O_t}
                G_t(z,w)\overline{M_t(w)}\,\dd M_t(w)\,\dd A(w).
 \label{cal:potential-differential}
\end{align}
The last line is defined by the weighted bracket-isometry limit of
compactly supported stochastic integrals.  The statement holds
simultaneously for countably many protected spatial points, and also
as a spatial distribution identity on protected open sets.
\end{lemma}

\begin{lemma}[Recovery and global localization]
\label{cal:recovery}
The continuous process $W$ is a semimartingale in the joint filtration.
\end{lemma}

\begin{lemma}[Spatial covariance realization]
\label{cal:covariance}
Locally in time there is a continuous increasing process $L$ such that
$\dd t$, $|\dd V|$, $\dd[W^{\mathrm M}]$, and all the spatial bracket measures
used below are absolutely continuous with respect to $\dd L$.  Outside one null set for $\dd L\,\dd\mathbb P$, write
\begin{equation}
 \tau=\frac{\dd t}{\dd L},\qquad
 \nu=\frac{\dd V}{\dd L},\qquad
 U=\dot W^{\mathrm M},\qquad A_{\mathrm{phys}}(w)=\dot M(w).
 \label{cal:clock-notation}
\end{equation}
The dots denote covariance vectors with respect to $\dd L$, not time
derivatives. These vectors lie in a real Hilbert space, complexified
for $A_{\mathrm{phys}}$.  Their scalar products are the corresponding
bracket densities.  The product is extended bilinearly, so
$A\cdot\overline A=|A|^2$ and $U\cdot U=|U|^2$.
The field $A_{\mathrm{phys}}$ is spatially smooth on every compact
subset of the live domain.  Spatial evaluations, derivatives, compact
tests, and the Green stochastic integrals in
\eqref{cal:potential-differential} have their covariance vectors on this
same full set.  In particular, for protected $z$,
\begin{equation}
 \int_{O_t}G_t(z,w)|A_{\mathrm{phys}}(w)|^2\,\dd A(w)<\infty
 \quad\text{for }\dd L\text{-almost every live time.}
 \label{cal:clock-green-integrability}
\end{equation}
\end{lemma}

\begin{proposition}[Moving-mark energy]\label{eng:energy}
For
\begin{equation}\label{eng:J-definition}
 J_t=\int_{\Hh}\frac{\mu_t(v)}{|v|^2}\,\dd A(v),
\end{equation}
there is a constant $K<\infty$ such that
\begin{equation}\label{eng:energy-bound}
 \E\int_0^\infty J_t^2\,\dd t
 \le K m^2\area(\Omega)<\infty.
\end{equation}
Consequently $J_t$ is finite for almost every capacity time, almost surely.
\end{proposition}

\begin{lemma}[Deterministic clock identities]\label{eng:clock}
Before the point's lifetime,
\begin{equation}\label{eng:clock-identities}
 Y_s=Y_0e^{-2s},\qquad
 \dd\log\crad_{O_{t(s)}}(w)=-4X_s^2\,\dd s,
 \qquad \dd t=r_s^2\,\dd s.
\end{equation}
The same identities hold after any live stopping time, with elapsed
capacity and clock times and the corresponding starting values.
\end{lemma}

\begin{lemma}[Restarted geometric estimates]\label{eng:restarts}
There are $a>0$, $K<\infty$, and $d_*>0$ with the following properties.
They hold conditionally on the past at every stopping time $\tau$ on the
event $w\in O_\tau$.
\begin{enumerate}
\item Translate and dilate the current half-plane chart so that its tip
is $0$, its target is $\infty$, and $|Z_\tau|=1$.  If
$X_\tau\le d_*$ and $x=\Rea(Z_\tau/|Z_\tau|)$, then, for
$0<d<d_*$, the probability that the restarted trace visits $B(x,d)$ is at
most $Kd^a$.
\item With $R=\crad_{O_\tau}(w)$ and $0<\varepsilon<1$,
\begin{equation}\label{eng:bulk-crad}
 \Prob\left\{
   \inf_{\tau\le t<T_w}\crad_{O_t}(w)<\varepsilon R
      \,\middle|\,\cF_\tau\right\}
 \le K\varepsilon^a.
\end{equation}
The infimum in this formula is strictly before the lifetime.  Conformal
radius is not assigned the value zero upon swallowing.
\end{enumerate}
These estimates remain valid for the inverse-clock stopping times and
the first angular-level stopping times used below.
\end{lemma}

\begin{lemma}[Reflected-ball estimate]\label{eng:reflection}
Consider a chordal Loewner trace in $\Hh$ with continuous driver, starting
from $0$.  Let its maps be $l_t$, so that $l_0$ is the identity.  Start a
point at $z_0=x+\ii X_0$ with $|z_0|=1$.  There are absolute constants
$c_0>0$ and $K<\infty$ such that, if $0<d<1/8$, $X_0\le c_0d$, and the trace avoids
$B(x,d)$, then up to the point's lifetime
\begin{equation}\label{eng:avoidance-deterministic}
 \sup_s\frac{X_s}{X_0}\le\frac Kd,
 \qquad
 \int_0^{\sigma_*}\frac{X_s}{X_0}\,\dd s\le\frac Kd.
\end{equation}
Consequently
\begin{equation}\label{eng:avoidance-square}
 \int_0^{\sigma_*}\left(\frac{X_s}{X_0}\right)^2\dd s
 \le\frac K{d^2}.
\end{equation}
\end{lemma}

\begin{lemma}[Supremum tails and occupation tightness]\label{eng:controls}
At every live restart, use elapsed point clock and write $X_0$ for its
starting angular coordinate.  There are $a>0$ and $K<\infty$ such that
\begin{equation}\label{eng:supremum-tail}
 \Prob\left\{\sup_{s\ge0}\frac{X_s}{X_0}>u
       \,\middle|\,\text{past}\right\}\le Ku^{-a},\qquad u\ge1.
\end{equation}
Moreover the conditional laws of
\begin{equation}\label{eng:occupation}
 I=\int_0^\infty\left(\frac{X_s}{X_0}\right)^2\dd s
\end{equation}
are uniformly tight, over all live restarts and all starting angles.
\end{lemma}

\begin{lemma}[Small-power contraction]\label{eng:decay}
There exist $p\in(0,1/4)$, $b>0$, and $K<\infty$ such that, from every
live restart,
\begin{equation}\label{eng:moment-decay}
 \E[X_s^p\mid\text{past}]\le K X_0^p e^{-bs},\qquad s\ge0.
\end{equation}
The same choice of $p$ has a uniformly bounded conditional $2p$-moment
of $\sup_{s\ge0}X_s/X_0$.
\end{lemma}

\begin{lemma}[Weighted clock integral]\label{eng:weighted}
For the $p$ in Lemma~\ref{eng:decay}, there are $\epsilon>0$ and
$K<\infty$ such that, uniformly over every initial live point,
\begin{equation}\label{eng:weighted-clock}
 \E\int_0^{\sigma_*}X_s^{2p}
 \left[
   \left(\frac{\sqrt{t(s)}}{r_s}\right)^\epsilon
  +\left(\frac{r_s}{\sqrt{t(s)}}\right)^\epsilon
 \right]\dd s\le K.
\end{equation}
Here $t(s)$ is capacity elapsed from the chosen starting instant.  The
value at $s=0$ is immaterial.
\end{lemma}

\begin{proposition}[Conditional unforced crossings]
\label{geo:g2}
The regularly drawn medial interfaces in domains of diameter at most
\(L\) satisfy condition G2 of \cite{KS}, uniformly over the allowed
meshes, domains, and thermal parameters.
\end{proposition}

\begin{lemma}[The gate product estimate]
\label{loc:failure}
With the first \(J\) levels and their finite set \(H\) fixed,
let all \(H\)-cut preimages have diameter at most \(\rho\).
Uniformly conditional on the two explored heads, the probability
that the shielding procedure fails is bounded by
\begin{equation}
 \begin{aligned}
 &K|H|\rho^\alpha\\
 &\quad+K\sum_{k>J}2^k
     \prod_{j_*\le j<k}K\bigl(2^{-j}(j+2)^2\bigr)^\alpha\\
 &\quad+K\delta_n^{-2}
     \prod_{j_*\le j\le N_n}K\bigl(2^{-j}(j+2)^2\bigr)^\alpha
 +o(1).
 \end{aligned}
 \label{loc:failure-bound}
\end{equation}
Here \(j_*\) and the constants are independent of \(J,n\)
and of the unbounded part of the domain. In particular,
the failure probability tends to zero by first taking
\(J\) large, then \(\rho\) small at that stage, and finally
the mesh sufficiently small.
\end{lemma}

\begin{proposition}[Reduction to bounded Dobrushin problems]
\label{loc:reduction}
From every admissible approximation sequence one can extract
a further subsequence and perform finite edge revelations
with success probability tending to one, so that on success:
\begin{enumerate}
\item the unqueried connecting domain \(\widehat\Omega_n\)
is a Dobrushin polygon on the original mesh with the
same thermal parameters and diameter at most \(2S+20\);
\item conditional on the complete revelation record, its
interface has the ordinary Dobrushin FK law;
\item every deterministic sequence of possible successful
outputs \((\widehat\Omega_n,\widehat a_n,\widehat b_n)\)
converges in the marked Carath\'eodory sense to
\((\Omega,a,b)\);
\item the normalized coordinates on the retained domain
are uniformly \(o(1)\) from its original normalized
coordinates, including prime-end occurrences, and
the removed endpoint heads have vanishing disc
diameter.
\end{enumerate}
All error bounds are uniform over successful outcomes.
\end{proposition}

\begin{lemma}\label{uni:weak}
Let $\kappa>0$, and let $b(t,x)$ be a fixed progressively measurable
nonanticipating real functional on continuous paths starting at zero.
There is at most one law of a continuous weak solution of
\begin{equation}\label{uni:generic-SDE}
 \dd X_t=\sqrt\kappa\,\dd B_t+b(t,X)\dd t,
 \qquad X_0=0,
\end{equation}
among solutions satisfying
\begin{equation}\label{uni:generic-energy}
 \int_0^T b(t,X)^2\dd t<\infty\quad\hbox{almost surely}
\end{equation}
for every finite $T$.
\end{lemma}

\begin{proposition}\label{uni:bounded}
Definition~\ref{def:law} determines exactly one law. Every
admissible approximation whose physical domains have a common
diameter bound converges to this law in the disc curve topology.
\end{proposition}

\begin{theorem}\label{thm:main}
There are constants $A>0$, $\sigma>0$, and $\lambda\in(0,1/2]$, independent
of $D,a,b$, such that the model \eqref{eq:model} has
\[
 \gamma_\delta\Longrightarrow\mathrm{SLE}_4(D;a,b),\qquad
 \frac{h_\delta-\E h_\delta}{\sigma}
       \Longrightarrow\mathrm{GFF}_D
\]
in the stated curve metric and as random distributions, respectively.
The constants and limiting mean are
\begin{align}
 v&=2/\sqrt3,&\sigma^2&=(vA)^{-1},&
 \lambda^2&=\frac{\pi}{8vA},\label{eq:target-constants}\\
 m_D(z)&=\lambda\bigl[\omega_D(z,A_+)-\omega_D(z,A_-)\bigr].&&&
 \label{eq:target-mean}
\end{align}
Here $\omega_D$ is harmonic measure and $A$ is the tangent-flux coefficient
defined in the cell construction. The stiffness is $vA$; no elementary
closed form for it is proposed.
\end{theorem}

\begin{lemma}[Zero-slope uniqueness]\label{b:zero-slope}
A controlled tangent solution of slope zero is spatially constant.
\end{lemma}

\begin{proposition}[The cell flux and weak equation]\label{b:cell}
Under the preceding inputs, $j(q)$ is well defined on the vector space of
attained slopes and is linear there. If any nonzero slope is attained,
every slope in $\R^2$ is attained and $j(q)=Aq$ for a finite scalar $A$.
For a stationary comparison with drift difference $n^{-2}b(x/n)$,
every subsequential expected macroscopic difference $m$ satisfies
\begin{equation}\label{b:weak-equation}
 \int j(\nabla m)\cdot\nabla f=\int b f,
 \qquad f\in C_c^\infty(U),
\end{equation}
in each limiting open region $U$ free of observations.
\end{proposition}

\begin{lemma}[Insulation]\label{c:insulation}
Outside a sparse set of initially selected boxes, every interior forcing
event in Lemma~\ref{c:force} has conditional probability at least $p_0/2$
of occurring in the uncut process, given the initial pair and transcript.
\end{lemma}

\begin{proposition}[Macroscopic exponential moments]\label{f:averages}
Fix $c,C>0$ and $B<\infty$. Let $R\ge1$ and let deterministic real weights
$q_x$ obey
\begin{equation}\label{f:weights}
 \sum_x|q_x|\le C,\qquad \max_x|q_x|\le CR^{-2},\qquad
 \operatorname{supp}q\subset Q,
 \quad \operatorname{diam}Q\le CR,
\end{equation}
where $Q$ is an ambient coordinate box. Assume either $\sum_xq_x=0$, or
there is a connected set of pins $K$, of diameter at least $cR$, such that
$K\cup Q$ lies in a coordinate box of diameter at most $CR$. For a sample
$h$ from $\mu_b$, there are $a>0$ and $M<\infty$, depending only on
$c,C,B$, such that
\begin{equation}\label{f:average-mgf}
 \E\exp\left(a\left|\sum_xq_xh(x)\right|\right)\le M.
\end{equation}
The conclusion is uniform over mixtures of bounded pin values whenever
conditioning on those values leaves exactly the specified uniform law.
\end{proposition}

\begin{lemma}[Triangular block deficit]\label{f:block}
For these fixed parameters there is $c_*>0$ such that, if $Q$ is
convex-good for $h$, $s=h|_{\partial Q}$,
$\chi:\partial Q\to\R$, and both $K_Q(s+\chi)$ and
$K_Q(s-\chi)$ have positive volume, then every two face centers $v,w$
satisfy
\begin{equation}\label{f:block-deficit}
 g_Q:=F_Q(s)-\tfrac12\bigl(F_Q(s+\chi)+F_Q(s-\chi)\bigr)
 \ge c_*|\chi(v)-\chi(w)|^2.
\end{equation}
\end{lemma}

\begin{lemma}[Zero-pinned sparse blocks]\label{f:sparse}
For every $\rho>0$ the fixed parameters above and a fixed enlargement
$Q_z^*$ can be chosen so that the following holds uniformly over zero-pinned
finite volumes. Declare every block within a fixed block distance of a pin
to be a pin block. Among the remaining blocks declare a block bad when it
fails \eqref{f:near}, the long-distance condition \eqref{f:far} on $Q_z^*$,
or one of the four non-tie tests. Then
\begin{equation}\label{f:animal}
 \Prob(A\text{ is entirely bad})\le\rho^{|A|}
\end{equation}
for every finite set $A$ of block indices. The collar defining pin blocks
contains all enlargements $Q_z^*$. Fixed finite thickenings of the bad set
also satisfy such a bound with an arbitrarily small parameter, after
adjusting the initial parameters.
\end{lemma}

\begin{lemma}[Sparse-hole extension]\label{f:hole}
Let a random bad set on the square grid satisfy \eqref{f:animal} with
sufficiently small parameter. Fill the bounded complementary components
of each bad star-connected cluster and retain its outermost filled hulls.
A fixed layer of enlargement is allowed. There is an extension procedure
which, for a field $u$ on good sites, fills each hole by its value at one
surrounding good site. Here good sites lie outside the filled holes and
good edges join neighboring good sites. Write $v$ for the resulting field.
A hole is incident to $z$ if it contains $z$ or a neighbor of $z$;
let $d_z$ be the largest diameter of an incident hole, zero if none,
and put $d_e=\max(d_x,d_y)$ for $e=\{x,y\}$. Uniformly in deterministic $z$,
\begin{equation}\label{f:hole-tail}
 \Prob(d_z\ge r)\le Ce^{-cr}.
\end{equation}
For every $1<p<2$, on a square of side $N$ with a fixed larger buffer,
\begin{equation}\label{f:hole-weighted}
 \|\nabla v\|_{\ell^p}
 \le E^{1/2}
 \left(\sum_e W_e^{2/(2-p)}a_e^{-p/(2-p)}\right)^{(2-p)/(2p)},
 \quad W_e\le C_p(1+d_e)^{2p},
\end{equation}
where $E=\sum_{e\text{ good}}a_e|\nabla u(e)|^2$, $a_e>0$.
In particular, bounded spatial moments of sufficiently high powers of
$d_e$ and $a_e^{-1}$ imply
\begin{equation}\label{f:hole-scaled}
 \|\nabla v\|_{\ell^p}\le C N^{2/p-1}\sqrt E.
\end{equation}
If $u$ is the restriction of a globally $K$-Lipschitz field on the grid,
then $|u(z)-v(z)|\le CK(1+d_z)$.

For every fixed $q,D<\infty$, the spatial average of $(1+d_z)^q$ in a
square of side $N$ is bounded by a deterministic constant outside an event
of probability $O(N^{-D})$. In a box of side $n$, these bounds hold
simultaneously on all subboxes of radius at least $n^{1/2}$, after altering
the failure exponent. Filling can be chosen equivariantly under translations
of the block grid. No reciprocal-weight assertion follows from sparsity
alone; those moments are separate hypotheses in \eqref{f:hole-weighted}.
\end{lemma}

\begin{lemma}[One-sample bounded-data comparison]\label{f:bounded}
There is a coupling of $h_b\sim\mu_b$ and one sample $h_0\sim\mu_0$ with
$|h_b-h_0|\le B$ at every vertex, whenever $|b|\le B$.
Consequently Proposition~\ref{f:averages} holds for bounded data and their
admissible mixtures.
\end{lemma}

\begin{lemma}[Strict filling with sign intervals]\label{f:strict-filling}
In a finite patch, prescribe arbitrary shell values, interior fixed pins
in $[-1/2,1/2]$, and intervals containing zero at any other prescribed
vertices. The intervals may be one-sided or of the form $[0,\eps]$.
Suppose a feasible filling $h$ satisfies
\begin{equation}\label{f:shell-room}
 |h(x)-b(s)|\le\operatorname{dist}(x,s)-2
\end{equation}
for every movable endpoint $x$ of a tested central edge and every shell
vertex $s$. If the edge is not fixed--fixed, there is a feasible filling
whose absolute gradient on that edge is at most $1/2$.
\end{lemma}

\begin{lemma}[The complete-crosscut upper bound]\label{g:upper-half}
For a complete single crosscut, the positive-side conditional mean is
at most \(1/2\), and the negative-side conditional mean is at least
\(-1/2\). This assertion is not made at an open interface tip.
\end{lemma}

\begin{lemma}[Clearance from the observer]\label{g:observer-landing}
Uniformly over the same bounded-data experiments,
\[
 \lim_{\eta\downarrow0}\limsup_{d\to\infty}
 \Prob\{\operatorname{dist}(v,\gamma)<\eta d\}=0.     \tag{GB4}
\]
This assertion does not require the lower bound in \((\mathrm{GB})\).
\end{lemma}

\begin{corollary}[Universality]\label{h:assembly}
For the model of Section~\ref{sec:model}, the constant
\[
 \lambda_*=\sigma\sqrt{\pi/8}
\]
belongs to $(0,1/2]$, is independent of the marked domain, and gives
the curve conclusion of Theorem~\ref{thm:main}. The field stiffness
is $vA=\sigma^{-2}$, and its limiting mean is the harmonic extension
of the prescribed exterior values.
\end{corollary}

\begin{lemma}[Tangential vector fields]\label{lem:shift-divergence}
Let $P\subset\mathbb R^N$ be a compact full-dimensional polytope, with
normalized Lebesgue measure. Suppose that $u:P\to\mathbb R^N$ is Lipschitz
and tangent to each facet of $P$. Then
\begin{equation}\label{eq:shift-divergence}
 \mathbb E\operatorname{div}u=0,\qquad
 \mathbb E(\operatorname{div}u)^2
 =\mathbb E\operatorname{tr}\bigl((Du)^2\bigr)
 \leq\mathbb E\|Du\|_{\mathrm{HS}}^2.
\end{equation}
\end{lemma}

\begin{lemma}[Quantitative averaged traces]\label{t:frostman}
Let $1<p<2$, $0<\alpha\le1$, and $p+\alpha>2$.  Every
$u\in W^{1,p}(Q^*)$ has a trace $T_\mu u\in L^1(\mu)$ for
$\mu\in\mathcal M_\alpha(M)$, and
\begin{equation}\label{t:trace-rate}
 \int|T_\mu u-P_ru|\dd\mu
 \le C r^\beta\|\nabla u\|_{L^p(Q^*)},\qquad
 \beta=1-\frac{2-\alpha}{p}>0.
\end{equation}
The constant is uniform over $\mathcal M_\alpha(M)$.

For a piecewise affine mesh function $u_n$, suppose instead that a measure
on mesh vertices satisfies
\begin{equation}\label{t:coarse-frostman}
 \mu_n(B(x,r))\le C(r+\ell_n/n)^\alpha,
 \qquad \mu_n(\overline Q)\le C,
\end{equation}
where $1\le\ell_n\le C(\log n)^C$.  Then, for fixed $r>0$,
\begin{equation}\label{t:mesh-trace-rate}
 \int|u_n-P_ru_n|\dd\mu_n
 \le C\left(r^\beta+
       \ell_n^{\alpha/p}n^{-\beta}\right)
       \|\nabla u_n\|_{L^p(Q^*)}.
\end{equation}
\end{lemma}

\begin{proposition}[Varying observed sets and filled values]
\label{t:varying-trace}
Let $K_n$ have the mesh thickness property with common constants and
converge in Hausdorff distance to $K$.  Let their mesh vertices carry
random values $z_n$, and let $U_n$ be random piecewise affine extensions
on $Q^*$.  Fix $3/2<p<2$.  Assume the following bounds, uniformly in $n$:
\begin{enumerate}
\item $\E\|U_n\|_{W^{1,p}}\le C$, and the means $\E U_n$ have a
      subsequence converging strongly in $L^p$ to $u$;
\item every vertex on $K_n$ can be moved to a retained vertex on $K_n$
      within distance $\ell_n/n$, where
      $\ell_n\le C(\log n)^C$;
\item $U_n=z_n$ at retained vertices, and their values satisfy
      Lemma~\ref{t:anchors} for some $q>3$, with $\E E_n\le C$;
\item exceptional events in these assertions have vanishing contribution
      to the Sobolev, anchor, and fixed-scale averaged quantities used
      here.
\end{enumerate}
Then $u$ has zero $1/2$-Frostman trace on $K$ and is zero Lebesgue-almost
everywhere on $K$.  If the original interpolated values also satisfy
\begin{equation}\label{t:original-filled}
 \E\|z_n-U_n\|_{L^1(Q)}\longrightarrow0,
\end{equation}
then the original mean responses have the same distributional limit,
including for smooth tests whose supports meet $K$.
\end{proposition}

\begin{lemma}[Uniform Brownian approach measures]\label{t:exit}
Let $K$ have continuum thickness, put $V=Q\setminus K$, and fix $z\in V$.
For sufficiently small $\eps>0$, let $V_\eps$ be the component containing
$z$ of $\{x\in V:\operatorname{dist}(x,V^c)>\eps\}$.  The exit law
$\mu_{z,\eps}$ of Brownian motion from $V_\eps$ satisfies
\begin{equation}\label{t:exit-frostman}
 \mu_{z,\eps}(B(x,r))\le C_z r^{1/2},
\end{equation}
uniformly in $\eps$.  The constant is uniform for $z$ a positive distance
from $K$, and depends on the common thickness constants and $Q$.
\end{lemma}

\begin{theorem}[Conditional covariance for deterministic strings]
\label{t:covariance}
Suppose the class $\mathcal S_n$ and the estimates
\ref{t:input-moments}--\ref{t:input-flux} hold, and set
$\sigma^2=(vA)^{-1}$.  Along every deterministic sequence
$s_n\in\mathcal S_n$ with $K_{n,s_n}\to K$ in Hausdorff distance,
\begin{equation}\label{t:conditional-mgf}
 \log\E_{n,s_n}e^{tX_{n,s_n}(f)}
 \longrightarrow
 \frac{t^2\sigma^2}{2}\langle f,G_{Q\setminus K}f\rangle
\end{equation}
for $t$ in a neighborhood of zero.  The conclusion holds for convergent
sequences of tests from a compact family and jointly for finitely many
tests.  In particular,
\begin{equation}\label{t:uniform-covariance}
 \sup_{s\in\mathcal S_n}\sup_{f,g\in\mathcal C}
 \left|\operatorname{Cov}_{n,s}(X_{n,s}(f),X_{n,s}(g))
       -\sigma^2\langle f,G_{V_{n,s}}g\rangle\right|
 \longrightarrow0.
\end{equation}
There is no requirement that $K$ have zero area or that the test supports
be disjoint from $K$.
\end{theorem}

\begin{corollary}[Transfer through an exact conditional kernel]
\label{t:random-covariance}
Let $S_n$ take values in $\mathcal S_n$, and suppose
\begin{equation}\label{t:kernel}
 \operatorname{Law}(h_n\mid S_n=s)=P_{n,s}
 \quad\hbox{for almost every }s.
\end{equation}
Then, for fixed tests or compact families as in Theorem~\ref{t:covariance},
the conditional covariance differs in $L^1$ from
$\sigma^2\langle f,G_{V_{n,S_n}}g\rangle$ by $o(1)$.
If $K_{n,S_n}$ converges in distribution to $K$, these random Green forms
converge in distribution and in expectation to those on $Q\setminus K$.
Convergence in $L^1$ to a limiting random form additionally requires that
the sets converge in probability on a common probability space.
\end{corollary}

\begin{theorem}\label{thm:main}
There are constants $A>0$, $\sigma>0$, and $\lambda\in(0,1/2]$, independent
of $D,a,b$, such that the model \eqref{eq:model} has
\[
 \gamma_\delta\Longrightarrow\mathrm{SLE}_4(D;a,b),\qquad
 \frac{h_\delta-\E h_\delta}{\sigma}
       \Longrightarrow\mathrm{GFF}_D
\]
in the stated curve metric and as random distributions, respectively.
The constants and limiting mean are
\begin{align}
 v&=2/\sqrt3,&\sigma^2&=(vA)^{-1},&
 \lambda^2&=\frac{\pi}{8vA},\label{eq:target-constants}\\
 m_D(z)&=\lambda\bigl[\omega_D(z,A_+)-\omega_D(z,A_-)\bigr].&&&
 \label{eq:target-mean}
\end{align}
Here $\omega_D$ is harmonic measure and $A$ is the tangent-flux coefficient
defined in the cell construction. The stiffness is $vA$; no elementary
closed form for it is proposed.
\end{theorem}

\begin{lemma}[Zero-slope uniqueness]\label{b:zero-slope}
A controlled tangent solution of slope zero is spatially constant.
\end{lemma}

\begin{proposition}[The cell flux and weak equation]\label{b:cell}
Under the preceding inputs, $j(q)$ is well defined on the vector space of
attained slopes and is linear there. If any nonzero slope is attained,
every slope in $\R^2$ is attained and $j(q)=Aq$ for a finite scalar $A$.
For a stationary comparison with drift difference $n^{-2}b(x/n)$,
every subsequential expected macroscopic difference $m$ satisfies
\begin{equation}\label{b:weak-equation}
 \int j(\nabla m)\cdot\nabla f=\int b f,
 \qquad f\in C_c^\infty(U),
\end{equation}
in each limiting open region $U$ free of observations.
\end{proposition}

\begin{lemma}[Insulation]\label{c:insulation}
Outside a sparse set of initially selected boxes, every interior forcing
event in Lemma~\ref{c:force} has conditional probability at least $p_0/2$
of occurring in the uncut process, given the initial pair and transcript.
\end{lemma}

\begin{proposition}[Macroscopic exponential moments]\label{f:averages}
Fix $c,C>0$ and $B<\infty$. Let $R\ge1$ and let deterministic real weights
$q_x$ obey
\begin{equation}\label{f:weights}
 \sum_x|q_x|\le C,\qquad \max_x|q_x|\le CR^{-2},\qquad
 \operatorname{supp}q\subset Q,
 \quad \operatorname{diam}Q\le CR,
\end{equation}
where $Q$ is an ambient coordinate box. Assume either $\sum_xq_x=0$, or
there is a connected set of pins $K$, of diameter at least $cR$, such that
$K\cup Q$ lies in a coordinate box of diameter at most $CR$. For a sample
$h$ from $\mu_b$, there are $a>0$ and $M<\infty$, depending only on
$c,C,B$, such that
\begin{equation}\label{f:average-mgf}
 \E\exp\left(a\left|\sum_xq_xh(x)\right|\right)\le M.
\end{equation}
The conclusion is uniform over mixtures of bounded pin values whenever
conditioning on those values leaves exactly the specified uniform law.
\end{proposition}

\begin{lemma}[Triangular block deficit]\label{f:block}
For these fixed parameters there is $c_*>0$ such that, if $Q$ is
convex-good for $h$, $s=h|_{\partial Q}$,
$\chi:\partial Q\to\R$, and both $K_Q(s+\chi)$ and
$K_Q(s-\chi)$ have positive volume, then every two face centers $v,w$
satisfy
\begin{equation}\label{f:block-deficit}
 g_Q:=F_Q(s)-\tfrac12\bigl(F_Q(s+\chi)+F_Q(s-\chi)\bigr)
 \ge c_*|\chi(v)-\chi(w)|^2.
\end{equation}
\end{lemma}

\begin{lemma}[Zero-pinned sparse blocks]\label{f:sparse}
For every $\rho>0$ the fixed parameters above and a fixed enlargement
$Q_z^*$ can be chosen so that the following holds uniformly over zero-pinned
finite volumes. Declare every block within a fixed block distance of a pin
to be a pin block. Among the remaining blocks declare a block bad when it
fails \eqref{f:near}, the long-distance condition \eqref{f:far} on $Q_z^*$,
or one of the four non-tie tests. Then
\begin{equation}\label{f:animal}
 \Prob(A\text{ is entirely bad})\le\rho^{|A|}
\end{equation}
for every finite set $A$ of block indices. The collar defining pin blocks
contains all enlargements $Q_z^*$. Fixed finite thickenings of the bad set
also satisfy such a bound with an arbitrarily small parameter, after
adjusting the initial parameters.
\end{lemma}

\begin{lemma}[Sparse-hole extension]\label{f:hole}
Let a random bad set on the square grid satisfy \eqref{f:animal} with
sufficiently small parameter. Fill the bounded complementary components
of each bad star-connected cluster and retain its outermost filled hulls.
A fixed layer of enlargement is allowed. There is an extension procedure
which, for a field $u$ on good sites, fills each hole by its value at one
surrounding good site. Here good sites lie outside the filled holes and
good edges join neighboring good sites. Write $v$ for the resulting field.
A hole is incident to $z$ if it contains $z$ or a neighbor of $z$;
let $d_z$ be the largest diameter of an incident hole, zero if none,
and put $d_e=\max(d_x,d_y)$ for $e=\{x,y\}$. Uniformly in deterministic $z$,
\begin{equation}\label{f:hole-tail}
 \Prob(d_z\ge r)\le Ce^{-cr}.
\end{equation}
For every $1<p<2$, on a square of side $N$ with a fixed larger buffer,
\begin{equation}\label{f:hole-weighted}
 \|\nabla v\|_{\ell^p}
 \le E^{1/2}
 \left(\sum_e W_e^{2/(2-p)}a_e^{-p/(2-p)}\right)^{(2-p)/(2p)},
 \quad W_e\le C_p(1+d_e)^{2p},
\end{equation}
where $E=\sum_{e\text{ good}}a_e|\nabla u(e)|^2$, $a_e>0$.
In particular, bounded spatial moments of sufficiently high powers of
$d_e$ and $a_e^{-1}$ imply
\begin{equation}\label{f:hole-scaled}
 \|\nabla v\|_{\ell^p}\le C N^{2/p-1}\sqrt E.
\end{equation}
If $u$ is the restriction of a globally $K$-Lipschitz field on the grid,
then $|u(z)-v(z)|\le CK(1+d_z)$.

For every fixed $q,D<\infty$, the spatial average of $(1+d_z)^q$ in a
square of side $N$ is bounded by a deterministic constant outside an event
of probability $O(N^{-D})$. In a box of side $n$, these bounds hold
simultaneously on all subboxes of radius at least $n^{1/2}$, after altering
the failure exponent. Filling can be chosen equivariantly under translations
of the block grid. No reciprocal-weight assertion follows from sparsity
alone; those moments are separate hypotheses in \eqref{f:hole-weighted}.
\end{lemma}

\begin{lemma}[One-sample bounded-data comparison]\label{f:bounded}
There is a coupling of $h_b\sim\mu_b$ and one sample $h_0\sim\mu_0$ with
$|h_b-h_0|\le B$ at every vertex, whenever $|b|\le B$.
Consequently Proposition~\ref{f:averages} holds for bounded data and their
admissible mixtures.
\end{lemma}

\begin{lemma}[Strict filling with sign intervals]\label{f:strict-filling}
In a finite patch, prescribe arbitrary shell values, interior fixed pins
in $[-1/2,1/2]$, and intervals containing zero at any other prescribed
vertices. The intervals may be one-sided or of the form $[0,\eps]$.
Suppose a feasible filling $h$ satisfies
\begin{equation}\label{f:shell-room}
 |h(x)-b(s)|\le\operatorname{dist}(x,s)-2
\end{equation}
for every movable endpoint $x$ of a tested central edge and every shell
vertex $s$. If the edge is not fixed--fixed, there is a feasible filling
whose absolute gradient on that edge is at most $1/2$.
\end{lemma}

\begin{lemma}[The complete-crosscut upper bound]\label{g:upper-half}
For a complete single crosscut, the positive-side conditional mean is
at most \(1/2\), and the negative-side conditional mean is at least
\(-1/2\). This assertion is not made at an open interface tip.
\end{lemma}

\begin{lemma}[Clearance from the observer]\label{g:observer-landing}
Uniformly over the same bounded-data experiments,
\[
 \lim_{\eta\downarrow0}\limsup_{d\to\infty}
 \Prob\{\operatorname{dist}(v,\gamma)<\eta d\}=0.     \tag{GB4}
\]
This assertion does not require the lower bound in \((\mathrm{GB})\).
\end{lemma}

\begin{proposition}[Uniform convergence of the whole curve]
\label{h:uniform-path}
If the hypotheses of Lemma~\ref{h:driving} hold for both exploration
directions, the interfaces converge to chordal $\mathrm{SLE}_4$ in
uniform Euclidean distance modulo increasing reparametrization.
\end{proposition}

\begin{corollary}[Universality]\label{h:assembly}
For the model of Section~\ref{sec:model}, the constant
\[
 \lambda_*=\sigma\sqrt{\pi/8}
\]
belongs to $(0,1/2]$, is independent of the marked domain, and gives
the curve conclusion of Theorem~\ref{thm:main}. The field stiffness
is $vA=\sigma^{-2}$, and its limiting mean is the harmonic extension
of the prescribed exterior values.
\end{corollary}

\begin{lemma}[Tangential vector fields]\label{lem:shift-divergence}
Let $P\subset\mathbb R^N$ be a compact full-dimensional polytope, with
normalized Lebesgue measure. Suppose that $u:P\to\mathbb R^N$ is Lipschitz
and tangent to each facet of $P$. Then
\begin{equation}\label{eq:shift-divergence}
 \mathbb E\operatorname{div}u=0,\qquad
 \mathbb E(\operatorname{div}u)^2
 =\mathbb E\operatorname{tr}\bigl((Du)^2\bigr)
 \leq\mathbb E\|Du\|_{\mathrm{HS}}^2.
\end{equation}
\end{lemma}

\begin{lemma}[Quantitative averaged traces]\label{t:frostman}
Let $1<p<2$, $0<\alpha\le1$, and $p+\alpha>2$.  Every
$u\in W^{1,p}(Q^*)$ has a trace $T_\mu u\in L^1(\mu)$ for
$\mu\in\mathcal M_\alpha(M)$, and
\begin{equation}\label{t:trace-rate}
 \int|T_\mu u-P_ru|\dd\mu
 \le C r^\beta\|\nabla u\|_{L^p(Q^*)},\qquad
 \beta=1-\frac{2-\alpha}{p}>0.
\end{equation}
The constant is uniform over $\mathcal M_\alpha(M)$.

For a piecewise affine mesh function $u_n$, suppose instead that a measure
on mesh vertices satisfies
\begin{equation}\label{t:coarse-frostman}
 \mu_n(B(x,r))\le C(r+\ell_n/n)^\alpha,
 \qquad \mu_n(\overline Q)\le C,
\end{equation}
where $1\le\ell_n\le C(\log n)^C$.  Then, for fixed $r>0$,
\begin{equation}\label{t:mesh-trace-rate}
 \int|u_n-P_ru_n|\dd\mu_n
 \le C\left(r^\beta+
       \ell_n^{\alpha/p}n^{-\beta}\right)
       \|\nabla u_n\|_{L^p(Q^*)}.
\end{equation}
\end{lemma}

\begin{proposition}[Varying observed sets and filled values]
\label{t:varying-trace}
Let $K_n$ have the mesh thickness property with common constants and
converge in Hausdorff distance to $K$.  Let their mesh vertices carry
random values $z_n$, and let $U_n$ be random piecewise affine extensions
on $Q^*$.  Fix $3/2<p<2$.  Assume the following bounds, uniformly in $n$:
\begin{enumerate}
\item $\E\|U_n\|_{W^{1,p}}\le C$, and the means $\E U_n$ have a
      subsequence converging strongly in $L^p$ to $u$;
\item every vertex on $K_n$ can be moved to a retained vertex on $K_n$
      within distance $\ell_n/n$, where
      $\ell_n\le C(\log n)^C$;
\item $U_n=z_n$ at retained vertices, and their values satisfy
      Lemma~\ref{t:anchors} for some $q>3$, with $\E E_n\le C$;
\item exceptional events in these assertions have vanishing contribution
      to the Sobolev, anchor, and fixed-scale averaged quantities used
      here.
\end{enumerate}
Then $u$ has zero $1/2$-Frostman trace on $K$ and is zero Lebesgue-almost
everywhere on $K$.  If the original interpolated values also satisfy
\begin{equation}\label{t:original-filled}
 \E\|z_n-U_n\|_{L^1(Q)}\longrightarrow0,
\end{equation}
then the original mean responses have the same distributional limit,
including for smooth tests whose supports meet $K$.
\end{proposition}

\begin{lemma}[Uniform Brownian approach measures]\label{t:exit}
Let $K$ have continuum thickness, put $V=Q\setminus K$, and fix $z\in V$.
For sufficiently small $\eps>0$, let $V_\eps$ be the component containing
$z$ of $\{x\in V:\operatorname{dist}(x,V^c)>\eps\}$.  The exit law
$\mu_{z,\eps}$ of Brownian motion from $V_\eps$ satisfies
\begin{equation}\label{t:exit-frostman}
 \mu_{z,\eps}(B(x,r))\le C_z r^{1/2},
\end{equation}
uniformly in $\eps$.  The constant is uniform for $z$ a positive distance
from $K$, and depends on the common thickness constants and $Q$.
\end{lemma}

\begin{theorem}[Conditional covariance for deterministic strings]
\label{t:covariance}
Suppose the class $\mathcal S_n$ and the estimates
\ref{t:input-moments}--\ref{t:input-flux} hold, and set
$\sigma^2=(vA)^{-1}$.  Along every deterministic sequence
$s_n\in\mathcal S_n$ with $K_{n,s_n}\to K$ in Hausdorff distance,
\begin{equation}\label{t:conditional-mgf}
 \log\E_{n,s_n}e^{tX_{n,s_n}(f)}
 \longrightarrow
 \frac{t^2\sigma^2}{2}\langle f,G_{Q\setminus K}f\rangle
\end{equation}
for $t$ in a neighborhood of zero.  The conclusion holds for convergent
sequences of tests from a compact family and jointly for finitely many
tests.  In particular,
\begin{equation}\label{t:uniform-covariance}
 \sup_{s\in\mathcal S_n}\sup_{f,g\in\mathcal C}
 \left|\operatorname{Cov}_{n,s}(X_{n,s}(f),X_{n,s}(g))
       -\sigma^2\langle f,G_{V_{n,s}}g\rangle\right|
 \longrightarrow0.
\end{equation}
There is no requirement that $K$ have zero area or that the test supports
be disjoint from $K$.
\end{theorem}

\begin{corollary}[Transfer through an exact conditional kernel]
\label{t:random-covariance}
Let $S_n$ take values in $\mathcal S_n$, and suppose
\begin{equation}\label{t:kernel}
 \operatorname{Law}(h_n\mid S_n=s)=P_{n,s}
 \quad\hbox{for almost every }s.
\end{equation}
Then, for fixed tests or compact families as in Theorem~\ref{t:covariance},
the conditional covariance differs in $L^1$ from
$\sigma^2\langle f,G_{V_{n,S_n}}g\rangle$ by $o(1)$.
If $K_{n,S_n}$ converges in distribution to $K$, these random Green forms
converge in distribution and in expectation to those on $Q\setminus K$.
Convergence in $L^1$ to a limiting random form additionally requires that
the sets converge in probability on a common probability space.
\end{corollary}
